/* css/style.css */
/* GENERATED from style.src.css by build_css.py - edit the .src file */
/* ==========================================================================
   IPTV Player — TV styles (designed for 1920x1080, right-to-left)
   Edit this file, then run build_css.py to produce style.css with the
   -webkit- prefixes older Samsung TVs need.
   Colours: background #120D17 · accent #F2455A
   ========================================================================== */

/* Kanaba's typeface: Tajawal, titles Bold and text Medium (SIL Open Font License, see fonts/Tajawal-OFL.txt).
   Only these two weights ship: 600 and up draw Bold, everything lighter draws Medium. */
@font-face { font-family: "Tajawal"; src: url("fonts/Tajawal-Medium.ttf") format("truetype"); font-weight: 500; font-style: normal; }
@font-face { font-family: "Tajawal"; src: url("fonts/Tajawal-Bold.ttf") format("truetype"); font-weight: 700; font-style: normal; }

html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #120D17; color: #F7F1F4; font-family: "Tajawal", "SamsungOneArabic", "Samsung One Arabic", "SamsungOne", "TizenSans", "Tizen Sans",
    "Noto Sans Arabic", "Noto Kufi Arabic", "Segoe UI", Tahoma, Arial, sans-serif; -webkit-font-smoothing: antialiased; -webkit-user-select: none; user-select: none; }
* { box-sizing: border-box; }
body.playing, body.playing #app { background: transparent; }

#av-player, #html5-player { position: absolute; left: 0; top: 0; width: 100%; height: 100%; z-index: 0; }
#html5-player { display: none; background: #000; }

#app { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; -webkit-transform-origin: 0 0; transform-origin: 0 0; z-index: 1; }

.screen { display: none; position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; background: #120D17; background-image: radial-gradient(circle at 85% -10%, #1d2a4a 0%, rgba(18,13,23,0) 55%),
                    radial-gradient(circle at 0% 110%, #2a1a10 0%, rgba(18,13,23,0) 45%); }
#scr-player { background: transparent; background-image: none; }

svg { fill: currentColor; }
.muted { color: #A89BAA; }

/* ---------- image placeholder (logo / poster) ---------- */
.ph { position: relative; display: inline-block; overflow: hidden; vertical-align: middle; background: #1a2235; border-radius: 10px; }
.ph .ph-txt { position: absolute; left: 0; top: 0; right: 0; bottom: 0; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; color: #5f6b85; font-weight: 700; font-size: 26px; }
.ph.loaded .ph-txt { display: none; }
.ph img { position: absolute; left: 0; top: 0; width: 100%; height: 100%; object-fit: contain; }

/* ---------- top bar ---------- */
.topbar { position: absolute; top: 0; left: 0; right: 0; height: 130px; padding: 0 60px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: space-between; justify-content: space-between; }
.tb-title { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.tb-title h1 { margin: 0; font-size: 46px; font-weight: 800; }
.tb-sep { width: 8px; height: 8px; border-radius: 4px; background: #F2455A; margin: 0 22px; }
.tb-sub { font-size: 32px; color: #B9ADBB; max-width: 620px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.clock { font-size: 38px; font-weight: 700; color: #dfe5ef; letter-spacing: 1px; }
.brand-sm { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; font-size: 40px; font-weight: 800; }
.logo-dot { width: 64px; height: 64px; border-radius: 18px; margin-left: 20px; background: -webkit-linear-gradient(315deg, #FF8A4C, #F2455A 48%, #C10A50); background: linear-gradient(135deg, #FF8A4C, #F2455A 48%, #C10A50); color: #fff; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.logo-dot svg { width: 46px; height: 46px; }

/* ---------- key hints ---------- */
.hints { font-size: 24px; color: #A89BAA; }
.kb { display: inline-block; min-width: 30px; padding: 2px 12px; margin: 0 14px 0 6px; border: 2px solid #5A4D5D; border-radius: 8px; font-size: 20px; color: #DCD1DD; text-align: center; vertical-align: middle; }
.kb.red, .kb.green, .kb.yellow, .kb.blue { min-width: 0; width: 24px; height: 24px; padding: 0; border: 0; border-radius: 12px; }
.kb.red { background: #e53935; } .kb.green { background: #43a047; }
.kb.yellow { background: #fdd835; } .kb.blue { background: #1e88e5; }

/* ---------- buttons ---------- */
.btn-row { display: -webkit-flex; display: flex; margin-top: 44px; }
.btn-row.center { -webkit-justify-content: center; justify-content: center; }
.btn { height: 80px; line-height: 80px; padding: 0 46px; margin-left: 22px; border-radius: 16px; font-size: 30px; font-weight: 700; white-space: nowrap; background: rgba(255,255,255,0.09); color: #F2EAF3; border: 3px solid transparent; -webkit-transition: -webkit-transform 0.15s, background 0.15s; transition: transform 0.15s, background 0.15s; }
.btn.primary { background: rgba(242,69,90,0.16); color: #FFB4A8; }
.btn.focused { background: #F2455A; color: #FFFFFF; -webkit-transform: scale(1.06); transform: scale(1.06); -webkit-box-shadow: 0 10px 30px rgba(242,69,90,0.35); box-shadow: 0 10px 30px rgba(242,69,90,0.35); }
.btn.danger.focused { background: #e5484d; color: #fff; -webkit-box-shadow: 0 10px 30px rgba(229,72,77,0.35); box-shadow: 0 10px 30px rgba(229,72,77,0.35); }
.btn.wide { text-align: center; margin: 10px 0 0; }

.chip { display: inline-block; padding: 4px 18px; margin: 0 0 10px 12px; border-radius: 30px; background: rgba(255,255,255,0.1); font-size: 24px; color: #d6dde9; }
.chip.now { background: #F2455A; color: #FFFFFF; font-weight: 700; }

.bar { position: relative; height: 8px; border-radius: 4px; background: rgba(255,255,255,0.18); overflow: hidden; }
.bar i { position: absolute; left: 0; top: 0; bottom: 0; background: #F2455A; border-radius: 4px; }

/* ---------- spinner / loader / toast ---------- */
.spinner { width: 86px; height: 86px; border-radius: 50%; border: 8px solid rgba(255,255,255,0.15); border-top-color: #F2455A; -webkit-animation: spin 0.9s linear infinite; animation: spin 0.9s linear infinite; }
@-webkit-keyframes spin { from { -webkit-transform: rotate(0deg); transform: rotate(0deg); } to { -webkit-transform: rotate(360deg); transform: rotate(360deg); } }
@keyframes spin { from { -webkit-transform: rotate(0deg); transform: rotate(0deg); } to { -webkit-transform: rotate(360deg); transform: rotate(360deg); } }

#loader { display: none; position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; z-index: 50; background: rgba(14,10,16,0.82); -webkit-flex-direction: column; flex-direction: column; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
#loader.show { display: -webkit-flex; display: flex; }
.loader-txt { margin-top: 34px; font-size: 32px; color: #DCD1DD; }

#toast { position: absolute; left: 50%; bottom: 90px; z-index: 60; max-width: 1300px; -webkit-transform: translateX(-50%) translateY(30px); transform: translateX(-50%) translateY(30px); opacity: 0; background: #1f293d; color: #fff; font-size: 30px; padding: 22px 46px; border-radius: 44px; -webkit-box-shadow: 0 16px 40px rgba(0,0,0,0.5); box-shadow: 0 16px 40px rgba(0,0,0,0.5); border: 2px solid rgba(242,69,90,0.35); -webkit-transition: opacity 0.25s, -webkit-transform 0.25s; transition: opacity 0.25s, transform 0.25s; white-space: nowrap; }
#toast.show { opacity: 1; -webkit-transform: translateX(-50%) translateY(0); transform: translateX(-50%) translateY(0); }

/* ---------- modal ---------- */
#modal { display: none; position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; z-index: 40; background: rgba(12,8,14,0.72); }
#modal.show { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.mdl-box { width: 940px; padding: 54px 60px; border-radius: 28px; text-align: center; background: #1C1522; border: 2px solid rgba(255,255,255,0.06); -webkit-box-shadow: 0 30px 80px rgba(0,0,0,0.6); box-shadow: 0 30px 80px rgba(0,0,0,0.6); }
.mdl-box h2 { margin: 0 0 18px; font-size: 42px; }
.mdl-box p { margin: 0; font-size: 30px; color: #B9ADBB; line-height: 1.6; white-space: pre-line; }
.mdl-box .btn { margin: 0 12px; }
.mdl-box.menu { width: 760px; text-align: right; padding: 44px 40px; }
.mdl-box.menu h2 { padding: 0 20px; }
#mdl-list { max-height: 588px; overflow: hidden; margin-top: 16px; }
.mitem { height: 76px; margin-bottom: 8px; padding: 0 24px; border-radius: 14px; font-size: 30px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.mitem.two { height: 104px; }
.mtxt b { display: block; font-weight: 700; }
.mtxt small { display: block; font-size: 22px; color: #A89BAA; margin-top: 4px; font-weight: 400; }
.vlist.active .mitem.focused .mtxt small { color: #FFFFFF; }
.mdl-hint { margin-top: 18px; padding: 0 20px; font-size: 22px; color: #A89BAA; }
#modal.side { background: -webkit-linear-gradient(right, rgba(12,8,14,0.85) 0%, rgba(12,8,14,0.55) 40%, rgba(12,8,14,0) 70%); background: linear-gradient(to left, rgba(12,8,14,0.85) 0%, rgba(12,8,14,0.55) 40%, rgba(12,8,14,0) 70%); }
#modal.side.show { -webkit-justify-content: flex-start; justify-content: flex-start; }
#modal.side .mdl-box { width: 700px; margin-right: 70px; }
.mcheck { width: 26px; height: 26px; border-radius: 13px; border: 3px solid #5A4D5D; margin-left: 22px; }
.mitem.sel .mcheck { border-color: #F2455A; background: #F2455A; -webkit-box-shadow: inset 0 0 0 5px #1C1522; box-shadow: inset 0 0 0 5px #1C1522; }
.vlist.active .mitem.focused { background: #F2455A; color: #FFFFFF; }
.vlist.active .mitem.focused .mcheck { border-color: #FFFFFF; }
.vlist.active .mitem.focused.sel .mcheck { background: #FFFFFF; -webkit-box-shadow: inset 0 0 0 5px #F2455A; box-shadow: inset 0 0 0 5px #F2455A; }

/* ==========================================================================
   LOGIN
   ========================================================================== */
.login-wrap { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; }
.login-brand { width: 720px; margin-left: 110px; }
.brand-head { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.logo-mark { width: 120px; height: 120px; border-radius: 34px; margin-left: 34px; -webkit-flex-shrink: 0; flex-shrink: 0; background: -webkit-linear-gradient(315deg, #FF8A4C, #F2455A 48%, #C10A50); background: linear-gradient(135deg, #FF8A4C, #F2455A 48%, #C10A50); color: #fff; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; -webkit-box-shadow: 0 24px 60px rgba(242,69,90,0.35); box-shadow: 0 24px 60px rgba(242,69,90,0.35); }
.logo-mark svg { width: 86px; height: 86px; }
.login-brand h1 { font-size: 66px; margin: 0 0 8px; font-weight: 800; }
.login-brand p { font-size: 28px; color: #B9ADBB; margin: 0; line-height: 1.5; }

.qr-card { margin-top: 54px; padding: 30px; border-radius: 30px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; background: rgba(28,21,34,0.85); border: 2px solid rgba(242,69,90,0.25); }
.qr-box { width: 300px; height: 300px; border-radius: 20px; overflow: hidden; background: #fff; -webkit-flex-shrink: 0; flex-shrink: 0; }
.qr-box canvas { display: block; width: 300px; height: 300px; }
.qr-text { margin-right: 34px; }
.qr-text h3 { margin: 0 0 12px; font-size: 38px; color: #FFB4A8; }
.qr-text p { margin: 0; font-size: 24px; color: #B9ADBB; line-height: 1.6; }
.qr-status { display: -webkit-inline-flex; display: inline-flex; -webkit-align-items: center; align-items: center; margin-top: 22px; padding: 10px 22px; border-radius: 30px; background: rgba(255,255,255,0.06); font-size: 23px; color: #DCD1DD; }
.qr-status i { width: 14px; height: 14px; border-radius: 7px; margin-left: 12px; background: #8E8191; }
.qr-status.ready i { background: #43c463; -webkit-animation: pulse 1.6s ease-in-out infinite; animation: pulse 1.6s ease-in-out infinite; }
.qr-status.connecting i { -webkit-animation: pulse 1s ease-in-out infinite; animation: pulse 1s ease-in-out infinite; }
.qr-status.offline { color: #ff9b72; }
.qr-status.offline i { background: #ff7b72; }
.qr-status.received { color: #FFB4A8; }
.qr-status.received i { background: #F2455A; }
@-webkit-keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.25; } 100% { opacity: 1; } }
@keyframes pulse { 0% { opacity: 1; } 50% { opacity: 0.25; } 100% { opacity: 1; } }

.login-form { width: 780px; padding: 56px 60px; border-radius: 32px; background: rgba(28,21,34,0.85); border: 2px solid rgba(255,255,255,0.06); }
.field { margin-bottom: 28px; }
.field label { display: block; font-size: 26px; color: #B9ADBB; margin-bottom: 12px; }
.field input { width: 100%; height: 86px; padding: 0 28px; border-radius: 16px; outline: none; font-size: 32px; color: #fff; font-family: inherit; text-align: left; background: rgba(255,255,255,0.05); border: 3px solid rgba(255,255,255,0.1); }
.field.focused input { border-color: #F2455A; background: rgba(242,69,90,0.08); }
.field input:focus { border-color: #F2455A; background: rgba(242,69,90,0.14); }
.lg-msg { min-height: 40px; margin: 22px 0 0; font-size: 28px; color: #ff7b72; text-align: center; }
.lg-tip { margin: 10px 0 0; font-size: 23px; color: #9F92A1; line-height: 1.6; text-align: center; }

/* ==========================================================================
   HOME — photo background, clock + dates, sections, ticker
   ========================================================================== */
#scr-home { background: #120D17; background-image: none; }
.hm-scene { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; overflow: hidden; }
.hm-fallback { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: #120D17; background-image: radial-gradient(90% 70% at 85% 0%, #3D1427 0%, rgba(18,13,23,0) 70%), linear-gradient(180deg, #24101C 0%, #120D17 60%, #0B070D 100%); }
.hm-photo.mark { display: none; }
.hm-photo { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; opacity: 0; background-size: cover; background-position: center center; background-repeat: no-repeat; -webkit-transition: opacity 1.2s; transition: opacity 1.2s; }
.hm-photo.loaded { opacity: 1; -webkit-animation: hmkb 60s ease-in-out infinite alternate; animation: hmkb 60s ease-in-out infinite alternate; }
.hm-photo.mark { background-size: 1300px 910px; background-position: -330px 500px; -webkit-animation: none; animation: none; }
@-webkit-keyframes hmkb { from { -webkit-transform: scale(1); transform: scale(1); } to { -webkit-transform: scale(1.06) translate(-10px, -6px); transform: scale(1.06) translate(-10px, -6px); } }
@keyframes hmkb { from { -webkit-transform: scale(1); transform: scale(1); } to { -webkit-transform: scale(1.06) translate(-10px, -6px); transform: scale(1.06) translate(-10px, -6px); } }
/* light shading only where text sits, so the photo stays clear */
.hm-shade { position: absolute; left: 0; top: 0; width: 1920px; height: 1080px; background: -webkit-linear-gradient(top, rgba(12,8,14,0.62) 0%, rgba(12,8,14,0.3) 14%, rgba(12,8,14,0) 27%),
              -webkit-linear-gradient(bottom, rgba(14,10,16,0.88) 0%, rgba(14,10,16,0.55) 14%, rgba(14,10,16,0) 30%),
              -webkit-linear-gradient(right, rgba(12,8,14,0.42) 0%, rgba(12,8,14,0) 32%); background: linear-gradient(to bottom, rgba(12,8,14,0.62) 0%, rgba(12,8,14,0.3) 14%, rgba(12,8,14,0) 27%),
              linear-gradient(to top, rgba(14,10,16,0.88) 0%, rgba(14,10,16,0.55) 14%, rgba(14,10,16,0) 30%),
              linear-gradient(to left, rgba(12,8,14,0.42) 0%, rgba(12,8,14,0) 32%); }

/* top bar */
.hm-top { position: absolute; top: 40px; left: 80px; right: 80px; height: 80px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: space-between; justify-content: space-between; }
.hm-top .brand-sm { text-shadow: 0 2px 12px rgba(0,0,0,0.5); }
.hm-actions { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; }
.hm-exp { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; height: 56px; padding: 0 24px; margin-left: 22px; border-radius: 28px; background: rgba(16,11,19,0.55); border: 2px solid rgba(255,255,255,0.12); font-size: 23px; color: #e3e8f1; }
.hm-exp i { width: 12px; height: 12px; border-radius: 6px; background: #43c463; margin-left: 12px; }
.hm-exp b { margin: 0 8px; color: #fff; }
.hm-exp.warn { color: #ffb4a8; border-color: rgba(255,123,114,0.5); }
.hm-exp.warn i { background: #ff7b72; }
.hm-btn { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; height: 64px; padding: 0 28px; margin-right: 16px; border-radius: 32px; background: rgba(16,11,19,0.55); border: 3px solid rgba(255,255,255,0.14); color: #F2EAF3; font-size: 26px; font-weight: 700; -webkit-transition: -webkit-transform 0.15s; transition: transform 0.15s; }
.hm-btn svg { width: 32px; height: 32px; margin-left: 12px; }
.hm-btn.focused { background: #F2455A; border-color: #F2455A; color: #FFFFFF; -webkit-transform: scale(1.08); transform: scale(1.08); -webkit-box-shadow: 0 10px 30px rgba(242,69,90,0.4); box-shadow: 0 10px 30px rgba(242,69,90,0.4); }

/* clock + dates (top right) */
.hm-hero { position: absolute; right: 80px; top: 140px; text-shadow: 0 3px 18px rgba(0,0,0,0.6), 0 1px 3px rgba(0,0,0,0.5); }
.hm-time { display: -webkit-flex; display: flex; -webkit-align-items: flex-end; align-items: flex-end; }
.hm-clock { font-size: 124px; font-weight: 800; line-height: 0.95; letter-spacing: -2px; color: #fff; }
.hm-ampm { font-size: 34px; font-weight: 700; color: #FFB4A8; margin: 0 16px 12px 0; }
.hm-date { font-size: 32px; font-weight: 700; margin-top: 12px; color: #fff; }
.hm-hijri { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; font-size: 28px; margin-top: 6px; color: #FFB4A8; font-weight: 700; }
.hm-hijri svg { width: 28px; height: 28px; margin-left: 12px; }


/* main sections (bottom) */
.hm-nav { position: absolute; left: 80px; right: 80px; top: 846px; height: 132px; display: -webkit-flex; display: flex; }
.hm-card { position: relative; -webkit-flex: 1; flex: 1; height: 132px; margin-left: 28px; padding: 0 28px; border-radius: 28px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; overflow: hidden; background: rgba(10,15,27,0.72); border: 3px solid rgba(255,255,255,0.12); -webkit-transition: -webkit-transform 0.18s, box-shadow 0.18s; transition: transform 0.18s, box-shadow 0.18s; }
.hm-card:last-child { margin-left: 0; }
.hc-ico { width: 80px; height: 80px; border-radius: 24px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; -webkit-justify-content: center; justify-content: center; color: #fff; -webkit-flex-shrink: 0; flex-shrink: 0; }
.hc-ico svg { width: 46px; height: 46px; }
.hc-txt { margin-right: 24px; overflow: hidden; }
.hc-txt b { display: block; font-size: 38px; font-weight: 800; }
.hc-txt span { display: block; font-size: 22px; color: #CBBFCC; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.c-live .hc-ico { background: -webkit-linear-gradient(300deg, #FF8A4C, #e5432b); background: linear-gradient(150deg, #FF8A4C, #e5432b); }
.c-vod .hc-ico { background: -webkit-linear-gradient(300deg, #8b73ff, #4127c9); background: linear-gradient(150deg, #8b73ff, #4127c9); }
.c-series .hc-ico { background: -webkit-linear-gradient(300deg, #1fc9a6, #0b7f86); background: linear-gradient(150deg, #1fc9a6, #0b7f86); }
.hm-card.focused { -webkit-transform: scale(1.05); transform: scale(1.05); border-color: rgba(255,255,255,0.95); -webkit-box-shadow: 0 24px 56px rgba(0,0,0,0.5); box-shadow: 0 24px 56px rgba(0,0,0,0.5); }
.hm-card.focused .hc-ico { background: rgba(255,255,255,0.22); }
.hm-card.focused .hc-txt span { color: rgba(255,255,255,0.9); }
.c-live.focused { background: -webkit-linear-gradient(300deg, #FF8A4C, #e5432b); background: linear-gradient(150deg, #FF8A4C, #e5432b); }
.c-vod.focused { background: -webkit-linear-gradient(300deg, #8b73ff, #4127c9); background: linear-gradient(150deg, #8b73ff, #4127c9); }
.c-series.focused { background: -webkit-linear-gradient(300deg, #1fc9a6, #0b7f86); background: linear-gradient(150deg, #1fc9a6, #0b7f86); }
.hm-nonews .hm-nav { top: 906px; }

/* news ticker */
.hm-news { position: absolute; left: 0; right: 0; bottom: 0; height: 66px; padding: 0 80px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; background: rgba(14,10,16,0.85); border-top: 2px solid rgba(242,69,90,0.3); }
.hm-nonews .hm-news { display: none; }
.nw-tag { display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; height: 40px; padding: 0 16px; border-radius: 12px; -webkit-flex-shrink: 0; flex-shrink: 0; background: #F2455A; color: #FFFFFF; font-size: 21px; font-weight: 800; }
.nw-tag svg { width: 24px; height: 24px; margin-left: 10px; }
.nw-box { position: relative; -webkit-flex: 1; flex: 1; height: 66px; overflow: hidden; margin: 0 28px; }
.nw-item { position: absolute; left: 0; right: 0; top: 0; height: 66px; display: -webkit-flex; display: flex; -webkit-align-items: center; align-items: center; white-space: nowrap; }
