/* css/touch.css */
/* ==========================================================================
   touch.css — phones, tablets and car screens (html.dev-touch).
   Everything here is laid out for the real screen size (html.native), with
   sizes in rem: 15px on a phone, 17px on a tablet. The TV styles stay as
   they are. Tajawal: titles Bold (700), everything else Medium (500).
   ========================================================================== */
html.dev-touch {
  --bg: #120D17; --panel: #1C1522; --raise: rgba(255,255,255,0.05); --line: rgba(255,255,255,0.08);
  --text: #F7F1F4; --muted: #A89BAA; --soft: #D6CBD7; --peach: #FF8A7A; --accent: #F2455A;
  --grad: linear-gradient(135deg, #FF8A4C, #F2455A 48%, #C10A50);
  --top: 62px; --tabs: 66px; --gut: 16px;
  /* one type scale for every screen: titles, section heads, text, details, labels */
  --fs-2xl: 2rem; --fs-xl: 1.6rem; --fs-lg: 1.3rem; --fs-md: 1.08rem; --fs-base: 0.95rem; --fs-sm: 0.85rem; --fs-xs: 0.75rem;
  font-size: 15px;
}
html.dev-touch.size-tablet { --top: 66px; --tabs: 64px; --gut: 22px; font-size: 15px; }
html.dev-touch.size-tablet.short { --top: 60px; --tabs: 60px; font-size: 14.5px; }
html.dev-touch, html.dev-touch body { font-weight: 500; }
html.dev-touch * { -webkit-tap-highlight-color: transparent; }
html.dev-touch button { font-family: inherit; cursor: pointer; }
html.dev-touch b, html.dev-touch h1, html.dev-touch h2, html.dev-touch h3 { font-weight: 700; }

.t-only { display: none !important; }
html.dev-touch .t-only { display: -webkit-flex !important; display: flex !important; }

/* ---------------- the page follows the real screen ---------------- */
html.native #app { width: 100%; height: 100%; }
html.native .screen { width: 100%; height: 100%; }
html.native .screen:not(#scr-player) { background: #120D17; background-image: radial-gradient(120% 60% at 85% -10%, #2A1424 0%, rgba(18,13,23,0) 60%); }

/* ---------------- top bar ---------------- */
.t-top { position: absolute; top: 0; left: 0; right: 0; z-index: 5; height: var(--top); padding: 0 var(--gut);
  display: flex; align-items: center; gap: 10px; background: rgba(18,13,23,0.92); }
.t-grow { flex: 1; }
.t-brand { display: flex; align-items: center; gap: 10px; font-size: var(--fs-lg); }
.t-logo { width: 36px; height: 36px; border-radius: 11px; background: var(--grad); color: #fff; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
.t-logo svg { width: 26px; height: 26px; }
.t-logo.big { width: 58px; height: 58px; border-radius: 18px; margin: 0 auto 10px; }
.t-logo.big svg { width: 42px; height: 42px; }
.t-title { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.t-title h1 { margin: 0; font-size: var(--fs-lg); white-space: nowrap; }
.t-title span { font-size: var(--fs-sm); color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.t-ibtn { width: 44px; height: 44px; flex-shrink: 0; padding: 0; border: 0; border-radius: 50%; background: var(--raise); color: var(--text);
  display: flex; align-items: center; justify-content: center; }
.t-ibtn svg { width: 22px; height: 22px; }
.t-ibtn.ring { border: 1.5px solid rgba(255,138,122,0.42); color: var(--peach); background: rgba(255,255,255,0.04); }
.t-ibtn.glass { background: rgba(18,13,23,0.55); color: #fff; }
.t-ibtn.on { color: #FFB020; }
.t-ibtn:active, .t-btn:active, .t-chip:active, .t-tab:active { opacity: 0.75; }

/* ---------------- feel: screens slide in softly, a press answers at once ---------------- */
@-webkit-keyframes tIn { from { opacity: 0; -webkit-transform: translateX(-18px); } to { opacity: 1; -webkit-transform: none; } }
@keyframes tIn { from { opacity: 0; transform: translateX(-18px); } to { opacity: 1; transform: none; } }
@-webkit-keyframes tBack { from { opacity: 0.4; -webkit-transform: translateX(14px); } to { opacity: 1; -webkit-transform: none; } }
@keyframes tBack { from { opacity: 0.4; transform: translateX(14px); } to { opacity: 1; transform: none; } }
html.native .screen.t-in { -webkit-animation: tIn 0.22s cubic-bezier(0.2, 0.8, 0.2, 1) both; animation: tIn 0.22s cubic-bezier(0.2, 0.8, 0.2, 1) both; }
html.native .screen.t-back { -webkit-animation: tBack 0.2s ease-out both; animation: tBack 0.2s ease-out both; }
.th-card, .tb-po, .tb-ch, .ts-ch, .t-btn, .t-ibtn, .t-chip, .t-srow, .tb-srow, .th-dot, .tp-dk, .tp-c {
  -webkit-transition: -webkit-transform 0.12s ease-out, opacity 0.12s, background-color 0.15s; transition: transform 0.12s ease-out, opacity 0.12s, background-color 0.15s; }
.th-card:active, .tl-cell:active .tb-po, .ts-grid .th-card:active { -webkit-transform: scale(0.96); transform: scale(0.96); }
.t-btn:active, .t-chip:active, .tp-dk:active, .tp-c:active { -webkit-transform: scale(0.95); transform: scale(0.95); }
/* rows far below the screen are not drawn until they come near */
.th-sec { content-visibility: auto; contain-intrinsic-size: 1px 320px; }

/* ---------------- the menu: a bar along the bottom (upright), a column at the side (sideways) ----------------
   it never floats over the content: the content stops where the menu starts */
html.dev-touch { --rail: 0px; --nav-b: calc(var(--tabs) + env(safe-area-inset-bottom, 0px)); }
html.dev-touch.land { --rail: 92px; --nav-b: 0px; }
html.dev-touch.size-phone.land { --rail: 78px; }
.t-tabs { position: absolute; left: 0; right: 0; bottom: 0; z-index: 6; height: var(--nav-b); padding: 6px 10px env(safe-area-inset-bottom, 0px);
  display: flex; gap: 4px; background: #17111B; border-top: 1px solid var(--line); }
.t-tab { flex: 1; padding: 0; border: 0; border-radius: 16px; background: none; color: #CFC3D0;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; font-size: var(--fs-xs); font-weight: 500; }
.t-tab svg { width: 23px; height: 23px; }
.t-tab.on { background: rgba(255,255,255,0.08); color: #FF7A5C; font-weight: 700; }
html.dev-touch.land .t-tabs { left: auto; top: 0; right: 0; bottom: 0; width: var(--rail); height: auto; padding: 12px 10px;
  flex-direction: column; justify-content: center; gap: 8px; border-top: 0; border-left: 1px solid var(--line); }
html.dev-touch.land .t-tab { flex: none; height: 68px; }
html.dev-touch.size-phone.land .t-tab { height: 58px; }
html.dev-touch.size-tablet.short .t-tab { height: 62px; }
.with-tabs > :not(.t-tabs) { right: var(--rail); }
.with-tabs .t-scroll, .with-tabs .tb-body { bottom: var(--nav-b); }

/* ---------------- shared pieces ---------------- */
.t-scroll { position: absolute; top: var(--top); left: 0; right: 0; bottom: 0; overflow-y: auto; overflow-x: hidden;
  -webkit-overflow-scrolling: touch; padding-bottom: 30px; }
.t-btn { height: 46px; padding: 0 22px; border: 0; border-radius: 999px; background: var(--grad); color: #fff; line-height: 1;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px; font-size: var(--fs-base); font-weight: 700; white-space: nowrap;
  box-shadow: 0 10px 26px rgba(242,69,90,0.28); }
.t-btn svg { width: 20px; height: 20px; }
.t-btn.ghost { background: rgba(255,255,255,0.1); box-shadow: none; font-weight: 500; }
.t-btn.wide { width: 100%; }
.t-btn:disabled { opacity: 0.4; box-shadow: none; }
.t-link { border: 0; background: none; padding: 6px 0; color: var(--peach); font-size: var(--fs-base); font-weight: 500; }
.muted { color: var(--muted); }

.t-chips { display: flex; gap: 8px; overflow-x: auto; padding: 10px var(--gut); scrollbar-width: none; -webkit-overflow-scrolling: touch; }
