html.size-tablet .tsg-stack { width: 170px; }
html.size-tablet.land .tsg-parts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); }

/* a film's page: the other parts of its series, this one marked */
.td-sagasec { margin-top: 22px; }
.td-sagasec .th-sec-head h2 .muted { margin-right: 6px; font-size: var(--fs-sm); font-weight: 500; }
