/* ==========================================================================
   THE MAC APP: the same screens with a mouse — a pointer, a lift under it,
   arrows at the ends of the rows, thin scroll bars
   ========================================================================== */
html.mac button, html.mac .tl-cell, html.mac [data-act] { cursor: pointer; }
html.mac input { cursor: text; }
html.mac .th-card .t-pic, html.mac .tl-cell .tb-po > .t-pic, html.mac .tl-cell .t-sg {
  -webkit-transition: -webkit-transform 0.18s ease, box-shadow 0.18s ease; transition: transform 0.18s ease, box-shadow 0.18s ease; }
html.mac .th-card:hover > .t-pic, html.mac .tl-cell:hover .tb-po > .t-pic { -webkit-transform: translateY(-4px); transform: translateY(-4px); box-shadow: 0 14px 28px rgba(0,0,0,0.5); }
html.mac .th-card:hover .t-sg, html.mac .tl-cell:hover .t-sg { -webkit-transform: translateY(-4px); transform: translateY(-4px); }
html.mac .th-card:hover b, html.mac .tl-cell:hover .tb-po b { color: #fff; }
html.mac .tsg-part:hover, html.mac .td-ep:hover, html.mac .tb-ch:hover, html.mac .ts-ch:hover { background: rgba(255,255,255,0.08); }
html.mac .tb-srow:not(.on):hover, html.mac .t-chip:not(.on):hover, html.mac .t-tab:not(.on):hover { background: rgba(255,255,255,0.07); }
html.mac .t-btn:hover, html.mac .t-ibtn:hover { -webkit-filter: brightness(1.12); filter: brightness(1.12); }
html.mac .t-link:hover { text-decoration: underline; }
html.mac ::-webkit-scrollbar { width: 10px; height: 10px; }
html.mac ::-webkit-scrollbar-track { background: transparent; }
html.mac ::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.16); border-radius: 6px; border: 2px solid transparent; background-clip: content-box; }
html.mac ::-webkit-scrollbar-thumb:hover { background-color: rgba(255,255,255,0.3); }
html.mac .th-row::-webkit-scrollbar { display: none; height: 0; }
/* the arrows at the ends of a row of posters */
html.mac .th-sec { position: relative; }
.mac-arw { position: absolute; z-index: 5; top: var(--arw-y, 50%); width: 44px; height: 44px; margin-top: -22px; padding: 0; border: 0; border-radius: 50%;
  background: rgba(18,13,23,0.86); color: #fff; box-shadow: 0 6px 18px rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center;
  opacity: 0; pointer-events: none; -webkit-transition: opacity 0.18s; transition: opacity 0.18s; }
.mac-arw svg { width: 22px; height: 22px; }
.mac-arw:hover { background: var(--grad); }
.mac-arw.prev { right: 8px; }
.mac-arw.next { left: 8px; }
.th-sec:hover .mac-arw { opacity: 1; pointer-events: auto; }
.th-sec[data-arw="none"] .mac-arw, .th-sec[data-arw="start"] .mac-arw.prev, .th-sec[data-arw="end"] .mac-arw.next { opacity: 0; pointer-events: none; }
/* room above the posters for the lift under the mouse (the row clips what goes past it) */
