.th-card .tb-osc { bottom: auto; top: 6px; }
.tb-po .tb-osc { bottom: auto; top: 6px; }
.tb-po .tb-star ~ .tb-osc { left: 40px; }

/* the playlist in use (shown when there are several): a tap opens the list to switch */
.t-pill { display: flex; align-items: center; gap: 6px; max-width: 42vw; height: 38px; margin-right: 10px; padding: 0 12px 0 10px; border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px; background: rgba(255,255,255,0.06); color: #fff; font: inherit; font-size: var(--fs-sm); font-weight: 700; }
.t-pill span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
