    }, 15000);
  }

  /* ---------- items: unify the 3 content types into one shape ---------- */
  function rating(r) {
    var v = parseFloat(r.rating);
    if (!(v > 0)) v = parseFloat(r.rating_5based) * 2;
    return v > 0 ? Math.round(v * 10) / 10 : null;
  }

  /* release year: the year field, the release date, or a year in the name like "(2025)" / "- 2026" */
  function yearOf(r) {
    var y = parseInt(r.year, 10);
    if (!(y > 1900)) y = parseInt(String(r.releaseDate || r.release_date || '').slice(0, 4), 10);
    if (!(y > 1900)) {
      var m = String(r.name || '').match(/(^|\D)(19|20)\d{2}(?!\d)/g);
      if (m) y = parseInt(m[m.length - 1].replace(/\D/g, ''), 10);
    }
    return y > 1900 && y <= new Date().getFullYear() + 1 ? y : 0;
  }

  /* newest first: by release year, then by the date it was added to the server */
  function newestFirst(list) {
    return list.slice().sort(function (a, b) { return ((b.year || 0) - (a.year || 0)) || ((b.added || 0) - (a.added || 0)); });
  }

  function norm(type, r) {
    if (type === 'live') {
      return { type: 'live', id: r.stream_id, name: r.name || '', icon: r.stream_icon || '',
        num: r.num, cat: r.category_id, archive: r.tv_archive };
    }
    if (type === 'vod') {
      return { type: 'vod', id: r.stream_id, name: r.name || '', icon: r.stream_icon || '',
        num: r.num, cat: r.category_id, ext: r.container_extension || 'mp4', rating: rating(r),
        year: yearOf(r), added: parseInt(r.added, 10) || 0 };
    }
    return { type: 'series', id: r.series_id, name: r.name || '', icon: r.cover || '',
      num: r.num, cat: r.category_id, rating: rating(r),
      year: yearOf(r), added: parseInt(r.last_modified, 10) || 0 };
  }

  var ACT = {
    live: ['get_live_categories', 'get_live_streams'],
    vod: ['get_vod_categories', 'get_vod_streams'],
    series: ['get_series_categories', 'get_series']
  };

  function getCategories(type, cb) {
    if (isM3U()) return M3U.getCategories(type, cb);
    var key = 'cats.' + type;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: ACT[type][0] }), function (err, data) {
      if (err) return cb(err);
      var list = [];
      if (data && data.length) {
        for (var i = 0; i < data.length; i++) {
          list.push({ id: String(data[i].category_id), name: data[i].category_name || '' });
        }
      }
      cache[key] = list;
      cb(null, list);
    });
  }

  /* categoryId null = everything of that type */
  function getStreams(type, categoryId, cb) {
    if (isM3U()) return M3U.getStreams(type, categoryId, cb);
    var key = 'streams.' + type + '.' + (categoryId === null ? '*' : categoryId);
    if (cache[key]) return cb(null, cache[key]);
    var p = { action: ACT[type][1] };
    if (categoryId !== null) p.category_id = categoryId;
    get(api(p), function (err, data) {
      if (err) return cb(err);
      var list = [];
      if (data && data.length) {
        for (var i = 0; i < data.length; i++) list.push(norm(type, data[i]));
      }
      if (type === 'live') {
        list.sort(function (a, b) { return (parseInt(a.num, 10) || 0) - (parseInt(b.num, 10) || 0); });
      }
      cache[key] = list;
      cb(null, list);
    }, 60000);
  }

  /* Arabic-friendly search normalisation */
  function simplify(s) {
    return String(s || '').toLowerCase()
      .replace(/[ً-ْـ]/g, '')        /* tashkeel + tatweel */
      .replace(/[آأإ]/g, 'ا')   /* آ أ إ -> ا */
      .replace(/ة/g, 'ه')                 /* ة -> ه */
      .replace(/ى/g, 'ي');                /* ى -> ي */
  }

  function search(type, query, cb) {
    var q = simplify(trim(query));
    if (!q) return cb(null, []);
    getStreams(type, null, function (err, all) {
      if (err) return cb(err);
      var out = [];
      for (var i = 0; i < all.length && out.length < 500; i++) {
        if (simplify(all[i].name).indexOf(q) !== -1) out.push(all[i]);
      }
      cb(null, out);
    });
  }

  function getVodInfo(id, cb) {
    if (isM3U()) return M3U.getVodInfo(id, cb);
    var key = 'vodinfo.' + id;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: 'get_vod_info', vod_id: id }), function (err, data) {
      if (err) return cb(err);
      cache[key] = data || {};
      cb(null, cache[key]);
    });
  }

  function getSeriesInfo(id, cb) {
    if (isM3U()) return M3U.getSeriesInfo(id, cb);
    var key = 'seriesinfo.' + id;
    if (cache[key]) return cb(null, cache[key]);
    get(api({ action: 'get_series_info', series_id: id }), function (err, data) {
      if (err) return cb(err);
      data = data || {};
      /* episodes: { "1":[...], "2":[...] } -> sorted seasons array */
      var eps = data.episodes || {};
      var seasons = [];
      for (var s in eps) {
        if (!eps.hasOwnProperty(s)) continue;
        var list = eps[s] || [];
        if (!list.length) continue;
        var arr = [];
        for (var i = 0; i < list.length; i++) {
          var e = list[i], ei = e.info || {};
          arr.push({
            id: e.id, num: parseInt(e.episode_num, 10) || (i + 1), season: s,
            title: e.title || '', ext: e.container_extension || 'mp4',
            image: ei.movie_image || ei.cover_big || '', plot: ei.plot || '',
            duration: ei.duration || '', secs: parseInt(ei.duration_secs, 10) || 0
          });
        }
        arr.sort(function (a, b) { return a.num - b.num; });
        seasons.push({ num: s, episodes: arr });
      }
      seasons.sort(function (a, b) { return (parseInt(a.num, 10) || 0) - (parseInt(b.num, 10) || 0); });
      var out = { info: data.info || {}, seasons: seasons };
      cache[key] = out;
      cb(null, out);
    });
  }

  /* now / next programme for a live channel (cached 3 minutes) */
  function getShortEpg(streamId, cb) {
    if (isM3U()) return M3U.getShortEpg(streamId, cb);
    var c = epgCache[streamId];
    if (c && U.now() - c.t < 180000) return cb(null, c.list);
    get(api({ action: 'get_short_epg', stream_id: streamId, limit: 4 }), function (err, data) {
      if (err) return cb(err);
      var raw = (data && data.epg_listings) || [];
      var list = [];
      for (var i = 0; i < raw.length; i++) {
        var p = raw[i];
        var st = parseInt(p.start_timestamp, 10) * 1000 || Date.parse(String(p.start).replace(' ', 'T'));
        var en = parseInt(p.stop_timestamp, 10) * 1000 || Date.parse(String(p.end || p.stop).replace(' ', 'T'));
        list.push({ title: U.b64(p.title), desc: U.b64(p.description), start: st, end: en });
      }
      var nowT = U.now();
      list = list.filter(function (x) { return !(x.end && x.end < nowT); });
      list.sort(function (a, b) { return a.start - b.start; });
      epgCache[streamId] = { t: U.now(), list: list };
      cb(null, list);
    }, 15000);
  }

  /* ---------- stream urls ---------- */
  function base(kind) {
    return acc.server + '/' + kind + '/' + encodeURIComponent(acc.username) + '/' + encodeURIComponent(acc.password) + '/';
  }
  function liveUrl(item, fmt) { return isM3U() ? M3U.urlOf(item) : base('live') + item.id + '.' + (fmt || 'ts'); }
  function movieUrl(item) { return isM3U() ? M3U.urlOf(item) : base('movie') + item.id + '.' + (item.ext || 'mp4'); }
  function episodeUrl(ep) { return isM3U() ? M3U.urlOf(ep) : base('series') + ep.id + '.' + (ep.ext || 'mp4'); }

  function clearCache() { cache = {}; epgCache = {}; }

  return {
    parseServer: parseServer, m3uLink: m3uLink, clean: trim, isM3U: isM3U, getText: getText, login: login, probe: probe, errorText: errorText,
    getCategories: getCategories, getStreams: getStreams, search: search, simplify: simplify, newestFirst: newestFirst,
    getVodInfo: getVodInfo, getSeriesInfo: getSeriesInfo, getShortEpg: getShortEpg,
    liveUrl: liveUrl, movieUrl: movieUrl, episodeUrl: episodeUrl,
    clearCache: clearCache,
    info: function () { return info; },
    account: function () { return acc; }
  };
})();

/* ==========================================================================
   m3u.js — plain M3U playlists (a link to a .m3u / .m3u8 list) and their
   XMLTV programme guide. Gives the same shapes as xtream.js, which hands
   every call over to this file when the playlist in use is an M3U link.

   A playlist entry:
     #EXTINF:-1 tvg-id=".." tvg-name="..." tvg-logo="..." group-title="...",Name
     http://...
   Live channels, films and series are told apart by the link
   (/movie/, /series/, a video file) and by "S01 E02" in the name.
   ========================================================================== */
var M3U = (function () {
  var data = null;          /* the parsed playlist in use */
  var guide = null;         /* XMLTV: channel id -> [{title, desc, start, end}] */
  var guideState = 'none';  /* none | loading | ready | failed */
  var guideWaiting = [];

  /* ---------- small helpers ---------- */
  function trim(s) { return String(s || '').replace(/^\s+|\s+$/g, ''); }

  /* stable id from the link, so favourites and "continue watching" survive a reload */
  function hash(s) {
    var h = 5381, i;
    for (i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
    return 'm' + (h >>> 0).toString(36) + s.length.toString(36);
  }

  function attr(line, name) {
    var re = new RegExp(name + '="([^"]*)"', 'i');
    var m = re.exec(line);
    return m ? trim(m[1]) : '';
  }

  function unesc(s) {
    return String(s || '').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
      .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'");
  }

  var VIDEO = /\.(mp4|mkv|avi|mov|wmv|m4v|webm|flv|mpg|mpeg|3gp)(\?|$)/i;
  var EPISODE = /^(.*?)[\s._\-|]*S(\d{1,2})[\s._\-]*E(\d{1,3})\b(.*)$/i;

  function extOf(url) {
    var m = /\.([a-z0-9]{2,4})(\?|$)/i.exec(url);
    return m ? m[1].toLowerCase() : 'mp4';
  }

  function yearOf(name) {
    var m = String(name || '').match(/(^|\D)(19|20)\d{2}(?!\d)/g);
    if (!m) return 0;
    var y = parseInt(m[m.length - 1].replace(/\D/g, ''), 10);
    return y > 1900 && y <= new Date().getFullYear() + 1 ? y : 0;
  }

  /* is this text a playlist? (and not a single HLS stream) */
  function looksLikeList(text) { return /#EXTINF/i.test(text.slice(0, 200000)); }
  function looksLikeStream(text) { return /#EXT-X-(TARGETDURATION|STREAM-INF|MEDIA-SEQUENCE)/i.test(text.slice(0, 20000)); }

  /* ---------- parsing ---------- */
  function parse(text, link) {
    var out = {
      epg: '', live: [], vod: [], series: [], episodes: {},
      cats: { live: [], vod: [], series: [] }, byId: {}
    };
    var catIndex = { live: {}, vod: {}, series: {} };
    var showIndex = {};

    function catOf(type, group) {
      var g = group || 'بدون تصنيف';
      var id = catIndex[type][g];
      if (!id) {
        id = type.charAt(0) + out.cats[type].length;
        catIndex[type][g] = id;
        out.cats[type].push({ id: id, name: g });
      }
      return id;
    }

    /* one HLS stream given as the "playlist": a single live channel */
    if (!looksLikeList(text) && looksLikeStream(text)) {
      var one = { type: 'live', id: hash(link), name: hostOf(link), icon: '', num: 1,
        cat: catOf('live', ''), url: link, epgId: '', archive: 0 };
      out.live.push(one);
      out.byId[one.id] = one;
      return out;
    }

    var head = /#EXTM3U[^\n]*/i.exec(text.slice(0, 2000));
    if (head) out.epg = attr(head[0], 'url-tvg') || attr(head[0], 'x-tvg-url') || '';
    if (out.epg.indexOf(',') !== -1) out.epg = trim(out.epg.split(',')[0]);

    var pos = 0, len = text.length, info = null, grp = '', n = 0;
    while (pos < len) {
      var end = text.indexOf('\n', pos);
      if (end === -1) end = len;
      var line = trim(text.slice(pos, end));
      pos = end + 1;
      if (!line) continue;
      if (line.charAt(0) === '#') {
        if (/^#EXTINF/i.test(line)) {
          /* the name is after the last comma that is outside quotes */
          var q = false, cut = -1;
          for (var i = 0; i < line.length; i++) {
            var c = line.charAt(i);
            if (c === '"') q = !q;
            else if (c === ',' && !q) cut = i;
          }
          info = {
            name: trim(cut >= 0 ? line.slice(cut + 1) : ''),
            id: attr(line, 'tvg-id'), tname: attr(line, 'tvg-name'),
            logo: attr(line, 'tvg-logo'), group: attr(line, 'group-title'),
            chno: attr(line, 'tvg-chno')
          };
          if (!info.group) info.group = grp;
        } else if (/^#EXTGRP:/i.test(line)) {
          /* a group line belongs to the entry it stands next to */
          grp = trim(line.slice(8));
          if (info && !info.group) info.group = grp;
        }
        continue;
      }
      /* a link line */
      if (!info) info = { name: '', id: '', tname: '', logo: '', group: grp, chno: '' };
      add(info, line);
      info = null;
      grp = '';
    }

    function add(inf, url) {
      var name = unesc(inf.name || inf.tname) || ('#' + (n + 1));
      var g = unesc(inf.group);
      var low = url.toLowerCase();
      var ep = EPISODE.exec(name);
      n++;
      if (ep && (low.indexOf('/series/') !== -1 || VIDEO.test(url))) {
        {
          var show = trim(ep[1]) || name;
          var sid = hash('s|' + g + '|' + show);
          var s = showIndex[sid];
          if (!s) {
            s = showIndex[sid] = { type: 'series', id: sid, name: show, icon: inf.logo, num: n,
              cat: catOf('series', g), rating: null, year: yearOf(show), added: 0 };
            out.series.push(s);
            out.byId[sid] = s;
            out.episodes[sid] = {};
          }
          if (!s.icon && inf.logo) s.icon = inf.logo;
          var sn = String(parseInt(ep[2], 10));
          var list = out.episodes[sid][sn] || (out.episodes[sid][sn] = []);
          var e = { id: hash(url), num: parseInt(ep[3], 10) || (list.length + 1), season: sn,
            title: name, ext: extOf(url), image: inf.logo, plot: '', duration: '', secs: 0, url: url };
          list.push(e);
          out.byId[e.id] = e;
          return;
        }
      }
      if (low.indexOf('/movie/') !== -1 || VIDEO.test(url)) {
        var v = { type: 'vod', id: hash(url), name: name, icon: inf.logo, num: n,
          cat: catOf('vod', g), ext: extOf(url), rating: null, year: yearOf(name), added: 0, url: url };
        out.vod.push(v);
        out.byId[v.id] = v;
        return;
      }
      var ch = { type: 'live', id: hash(url), name: name, icon: inf.logo,
        num: parseInt(inf.chno, 10) || out.live.length + 1, cat: catOf('live', g),
        url: url, epgId: inf.id || inf.tname || name, archive: 0 };
      out.live.push(ch);
      out.byId[ch.id] = ch;
    }
    return out;
  }

  function hostOf(url) {
    var m = /^[a-z]+:\/\/([^\/:?#]+)/i.exec(String(url || ''));
    return m ? m[1] : String(url || '');
  }

  /* ---------- loading the playlist ---------- */
  /* cb(err, parsed) — does not change the playlist in use */
  function fetchList(link, cb) {
    Xtream.getText(link, function (err, text) {
      if (err) return cb(err);
      text = String(text || '');
      if (!looksLikeList(text) && !looksLikeStream(text)) return cb({ code: 'notlist' });
      var parsed;
      try { parsed = parse(text.replace(/\r/g, ''), link); }
      catch (e) { return cb({ code: 'parse' }); }
      if (!parsed.live.length && !parsed.vod.length && !parsed.series.length) return cb({ code: 'empty' });
      cb(null, parsed);
    }, 90000);
  }

  function summary(p) {
    return { kind: 'm3u', counts: { live: p.live.length, vod: p.vod.length, series: p.series.length }, epg: p.epg };
  }

  /* makes this playlist the one in use; also starts loading its guide */
  function login(acc, cb) {
    fetchList(acc.url, function (err, parsed) {
      if (err) return cb(err);
      data = parsed;
      guide = null; guideState = 'none';
      var epg = trim(acc.epg) || parsed.epg;
      if (epg && parsed.live.length) loadGuide(epg);
      cb(null, summary(parsed));
    });
  }

  function probe(acc, cb) {
    fetchList(acc.url, function (err, parsed) { cb(err, parsed ? summary(parsed) : null); });
  }

  /* ---------- the Xtream-shaped calls ---------- */
  function getCategories(type, cb) { cb(null, data ? data.cats[type].slice() : []); }

  function getStreams(type, categoryId, cb) {
    if (!data) return cb(null, []);
    var all = data[type], out = [];
    if (categoryId === null) return cb(null, all.slice());
    for (var i = 0; i < all.length; i++) if (all[i].cat === categoryId) out.push(all[i]);
    cb(null, out);
  }

  function getVodInfo(id, cb) {
    var it = data && data.byId[id];
    cb(null, { info: it ? { name: it.name, movie_image: it.icon } : {}, movie_data: {} });
  }

  function getSeriesInfo(id, cb) {
    var it = data && data.byId[id], eps = (data && data.episodes[id]) || {}, seasons = [];
    for (var s in eps) {
      if (!eps.hasOwnProperty(s)) continue;
      var arr = eps[s].slice().sort(function (a, b) { return a.num - b.num; });
      seasons.push({ num: s, episodes: arr });
    }
    seasons.sort(function (a, b) { return (parseInt(a.num, 10) || 0) - (parseInt(b.num, 10) || 0); });
    cb(null, { info: it ? { name: it.name, cover: it.icon } : {}, seasons: seasons });
  }

  /* saved favourites and history keep only the id: the link comes from the list */
  function urlOf(item) {
    if (!item) return '';
    if (item.url) return item.url;
    var it = data && data.byId[item.id];
    return (it && it.url) || '';
  }

  /* ---------- XMLTV programme guide ---------- */
  /* "20261125200000 +0300" -> ms */
  function xmltvTime(s) {
    var m = /^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?\s*([+-]\d{4})?/.exec(trim(s));
    if (!m) return 0;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +(m[6] || 0));
    if (m[7]) {
      var sign = m[7].charAt(0) === '-' ? -1 : 1;
      t -= sign * (parseInt(m[7].substr(1, 2), 10) * 60 + parseInt(m[7].substr(3, 2), 10)) * 60000;
    }
    return t;
  }

  function tagText(block, tag) {
    var m = new RegExp('<' + tag + '[^>]*>([\\s\\S]*?)</' + tag + '>', 'i').exec(block);
    if (!m) return '';
    return trim(unesc(m[1].replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')));
  }

  /* keeps only what is useful now: from 3 hours ago to 36 hours ahead,
     and only for channels that are in the playlist */
  function parseGuide(xml) {
    var want = {}, i;
    if (data) for (i = 0; i < data.live.length; i++) if (data.live[i].epgId) want[data.live[i].epgId.toLowerCase()] = true;
    var from = U.now() - 3 * 3600000, to = U.now() + 36 * 3600000;
    var map = {}, pos = 0, count = 0;
    while (true) {
      var st = xml.indexOf('<programme', pos);
      if (st === -1) break;
      var en = xml.indexOf('</programme>', st);
      if (en === -1) break;
      pos = en + 12;
      var openEnd = xml.indexOf('>', st);
      var open = xml.slice(st, openEnd + 1);
      var ch = attr(open, 'channel').toLowerCase();
      if (!ch || !want[ch]) continue;
      var a = xmltvTime(attr(open, 'start')), b = xmltvTime(attr(open, 'stop'));
      if (!a || (b && b < from) || a > to) continue;
      var block = xml.slice(openEnd + 1, en);
      (map[ch] || (map[ch] = [])).push({ title: tagText(block, 'title'), desc: tagText(block, 'desc'), start: a, end: b });
      count++;
    }
    for (var k in map) if (map.hasOwnProperty(k)) map[k].sort(function (x, y) { return x.start - y.start; });
    return { map: map, count: count };
  }

  function guideDone(ok) {
    guideState = ok ? 'ready' : 'failed';
    var w = guideWaiting; guideWaiting = [];
    for (var i = 0; i < w.length; i++) w[i]();
  }

  function loadGuide(link) {
    guideState = 'loading';
    var forData = data;
    Xtream.getText(link, function (err, xml) {
      if (forData !== data) return;          /* another playlist since */
      if (err || !xml) { guideDone(false); return; }
      try { guide = parseGuide(String(xml)).map; guideDone(true); }
      catch (e) { guideDone(false); }
    }, 120000, true);
  }

  function getShortEpg(streamId, cb) {
    var ch = data && data.byId[streamId];
    if (!ch || !ch.epgId) return cb(null, []);
    if (guideState === 'loading') {
      guideWaiting.push(function () { getShortEpg(streamId, cb); });
      return;
    }
    var list = (guide && guide[ch.epgId.toLowerCase()]) || [], now = U.now(), out = [];
    for (var i = 0; i < list.length && out.length < 4; i++) if (!(list[i].end && list[i].end < now)) out.push(list[i]);
    cb(null, out);
  }

  function clear() { /* the parsed list stays until another playlist logs in */ }

  return {
    login: login, probe: probe, parse: parse, xmltvTime: xmltvTime, parseGuide: parseGuide,
    getCategories: getCategories, getStreams: getStreams,
    getVodInfo: getVodInfo, getSeriesInfo: getSeriesInfo, getShortEpg: getShortEpg,
    urlOf: urlOf, clear: clear, hostOf: hostOf,
    guideState: function () { return guideState; },
    counts: function () { return data ? summary(data).counts : null; }
  };
})();

/* ==========================================================================
   pair.js — "login from phone" on the TV side.

   1. The TV makes a random channel name + a random 16-byte key.
   2. The QR code holds  <pairPage>#t=<channel>&k=<key>.
      The part after # never leaves the phone, so the relay never sees the key.
   3. The phone page encrypts {server, user, pass} with the key and posts it
      to the relay channel. The TV listens on that channel, checks and decrypts.
   ========================================================================== */
var Pair = (function () {
  var session = null;
  var xhr = null;
