    m.className = '';
    m.innerHTML = '<div class="mdl-box"><h2>' + U.esc(opts.title || '') + '</h2>' +
      (opts.text ? '<p>' + U.esc(opts.text) + '</p>' : '') +
      '<input id="mdl-pin" class="pin-input" type="password" inputmode="numeric" pattern="[0-9]*" maxlength="4" dir="ltr" autocomplete="off">' +
      '<p class="pin-err" id="mdl-pin-err">' + U.esc(opts.error || '') + '</p></div>';
