      '<input id="mdl-txt" class="txt-input" type="text" maxlength="40" autocomplete="off" autocorrect="off" spellcheck="false" enterkeyhint="done"' +
      ' value="' + U.esc(opts.value || '') + '" placeholder="' + U.esc(opts.placeholder || '') + '">' +
