    }, { passive: true });
    box.addEventListener('click', function (e) {
      if (U.now() - lastHold < 600) return;
      var c = e.target;
      while (c && c !== box && !(c.getAttribute && c.getAttribute('data-i'))) c = c.parentNode;
      if (!c || c === box) return;
      var i = parseInt(c.getAttribute('data-i'), 10);
      if (self.items[i] && o.onTap) o.onTap(self.items[i], i, c);
    });
