  };
  TList.prototype.clear = function () { this.rows = {}; this.sp.innerHTML = ''; this.win = null; };
  TList.prototype.refresh = function () { this.clear(); this.draw(true); };
  TList.prototype.draw = function (force) {
    var w = this.box.clientWidth, h = this.box.clientHeight;
    if (!w) return;
    var o = this.o, cols = Math.max(1, o.cols ? o.cols(w) : 1), rh = o.rowH(w, cols);
    var pt = o.padTop || 0, pb = o.padBottom || 0;
    var n = this.items.length, nrows = Math.ceil(n / cols);
    if (this.cols !== cols || this.rh !== rh) { this.cols = cols; this.rh = rh; this.clear(); force = true; }
    this.sp.style.height = (pt + nrows * rh + pb) + 'px';
    var st = this.box.scrollTop;
    var first = Math.max(0, Math.floor((st - pt) / rh) - 3);
    var last = Math.min(nrows - 1, Math.ceil((st - pt + h) / rh) + 3);
    if (!force && this.win && this.win[0] === first && this.win[1] === last) return;
    this.win = [first, last];
    var r, k;
    for (k in this.rows) {
      r = parseInt(k, 10);
      if (r < first || r > last) { this.sp.removeChild(this.rows[k]); delete this.rows[k]; }
    }
    var frag = document.createDocumentFragment();
    for (r = first; r <= last; r++) {
      if (this.rows[r]) continue;
      var row = document.createElement('div');
      row.className = 'tl-row';
      row.style.top = (pt + r * rh) + 'px';
      row.style.height = rh + 'px';
      var html = '';
      for (var c = 0; c < cols; c++) {
        var i = r * cols + c;
        if (i >= n) break;
        html += '<div class="tl-cell" data-i="' + i + '" style="width:' + (100 / cols) + '%">' + o.render(this.items[i], i) + '</div>';
      }
      row.innerHTML = html;
      this.rows[r] = row;
      frag.appendChild(row);
