      '<div class="t-sheet-head"><h2>' + esc(o.title || '') + '</h2><button type="button" class="t-ibtn" data-x="1" aria-label="إغلاق">' + ICON.close + '</button></div>';
    if (o.search) h += '<div class="t-field t-sheet-find">' + ICON.search + '<input type="search" placeholder="ابحث في الأقسام" autocomplete="off"></div>';
