      var s = '';
      for (var i = 0; i < items.length; i++) {
        var it = items[i];
        s += '<button type="button" class="t-srow' + (it.selected ? ' on' : '') + '" data-i="' + i + '">' +
          (it.icon ? '<span class="t-srow-ic">' + it.icon + '</span>' : '') +
          '<span class="t-srow-t"><b>' + esc(it.label) + '</b>' + (it.sub ? '<small>' + esc(it.sub) + '</small>' : '') + '</span>' +
          (it.selected ? '<span class="t-srow-ic ok">' + ICON.check + '</span>' : '') +
