      }
      listEl.innerHTML = s || '<p class="t-empty-s">لا توجد نتائج</p>';
    }
    draw(o.items);
    var sel = sheetEl.querySelector('.t-srow.on');
    if (sel) listEl.scrollTop = Math.max(0, sel.offsetTop - 120);
    if (o.search) {
      var inp = sheetEl.querySelector('input');
      inp.addEventListener('input', function () {
        var q = Xtream.simplify ? Xtream.simplify(inp.value) : inp.value.toLowerCase();
        if (!q) { draw(o.items); return; }
        var out = [];
        for (var i = 0; i < o.items.length; i++) {
          var l = Xtream.simplify ? Xtream.simplify(o.items[i].label) : o.items[i].label.toLowerCase();
          if (l.indexOf(q) !== -1) out.push(o.items[i]);
