Screens.login = {
  f: 0,                 /* focused row: 0 server, 1 user, 2 pass, 3 button */
  params: {},
  busy: false,
  mode: 'xtream',       /* 'm3u': row 0 is the list link, row 1 its guide link, no row 2 */

