  afterServer: function () {
    var ins = this.inputs();
    var p = Xtream.parseServer(ins[0].value);
    if (!p.username && Xtream.m3uLink(ins[0].value) && (this.mode === 'm3u' || (!ins[1].value && !ins[2].value))) {
      if (this.mode !== 'm3u') { ins[1].value = ''; UI.toast('رابط قائمة M3U — أضف رابط دليل البرامج إن وُجد'); }
      this.setMode('m3u');
      return false;
    }
    if (this.mode === 'm3u') { this.setMode('xtream'); ins[1].value = ''; }
    if (p.username) {
      ins[0].value = p.server;
      ins[1].value = p.username;
      ins[2].value = p.password || '';
      UI.toast('تم استخراج بيانات الدخول من الرابط');
      return true;
    }
    return false;
  },

  onKey: function (k) {
    var ins = this.inputs();
    if (this.busy) return;
    switch (k) {
      case 'up': if (this.f > 0) { this.f--; if (this.f === 2 && this.mode === 'm3u') this.f = 1; this.draw(); } break;
      case 'down': if (this.f < 3) { this.f++; if (this.f === 2 && this.mode === 'm3u') this.f = 3; this.draw(); } break;
      case 'enter':
        if (this.f < 3) this.edit(); else this.submit();
        break;
      case 'imedone':
        if (this.f < 3) ins[this.f].blur();
        if (this.f === 0 && this.afterServer()) this.f = 3;
        else if (this.f < 3) this.f++;
        if (this.f === 2 && this.mode === 'm3u') this.f = 3;
        this.draw();
        break;
      case 'imecancel':
        if (this.f < 3) ins[this.f].blur();
        this.draw();
        break;
      case 'imeup':
        if (this.f < 3) ins[this.f].blur();
        if (this.f > 0) this.f--;
        if (this.f === 2 && this.mode === 'm3u') this.f = 1;
        this.draw();
        break;
      case 'back':
        if (this.params.fromSettings || this.params.add) App.back();
        else App.exitConfirm();
        break;
    }
  },

  /* from the playlists screen: check the new playlist and keep it (the one in use stays) */
  addPlaylist: function (acc) {
    var self = this;
    UI.loading(true, 'جاري التحقق من قائمة التشغيل...');
    Xtream.probe(acc, function (err) {
      self.busy = false;
      UI.loading(false);
      if (err && /^(auth|notlist|empty)$/.test(err.code)) {
        self.msg(Xtream.errorText(err));
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      var old = self.params.preset, before = Store.activePlaylist();
      var wasActive = !!(old && before && before.id === old.id);
      if (old) acc.name = old.name;
      var pl = Store.savePlaylist(acc);
      if (old && pl.id !== old.id) {
        /* edited into a different link / account: it replaces the old entry */
        if (wasActive) Store.usePlaylist(pl.id);
        Store.removePlaylist(old.id);
      }
      Pair.stop();
      if (old) UI.toast('تم حفظ التعديل ✓');
      else UI.toast(err ? 'تمت إضافة القائمة لكنها لا تعمل حالياً' : 'تمت إضافة قائمة التشغيل ✓');
      if (wasActive) { Store.usePlaylist(pl.id); Xtream.clearCache(); App.reconnect(); return; }
      App.back({ added: pl.id });
    });
  },

  submit: function () {
    var self = this;
    var ins = this.inputs();
    this.afterServer();
    if (this.mode === 'm3u') {
      var link = Xtream.m3uLink(ins[0].value);
      if (!link) { this.msg('اكتب رابط قائمة M3U'); this.f = 0; this.draw(); return; }
      var epg = String(ins[1].value).replace(/^\s+|\s+$/g, '');
      if (epg && !/^https?:\/\//i.test(epg)) epg = 'http://' + epg;
      this.go({ kind: 'm3u', url: link, epg: epg });
      return;
    }
    var p = Xtream.parseServer(ins[0].value);
    var acc = {
      server: p.server,
      username: Xtream.clean(ins[1].value),
      password: Xtream.clean(ins[2].value)
    };
    if (!acc.server) { this.msg('اكتب رابط السيرفر'); this.f = 0; this.draw(); return; }
    if (!acc.username) { this.msg('اكتب اسم المستخدم'); this.f = 1; this.draw(); return; }
    if (!acc.password) { this.msg('اكتب كلمة المرور'); this.f = 2; this.draw(); return; }
    this.go(acc);
  },

  go: function (acc) {
    var self = this;
    this.msg('');
    this.busy = true;
    if (this.params.add) { this.addPlaylist(acc); return; }
    UI.loading(true, acc.kind === 'm3u' ? 'جاري تحميل قائمة التشغيل...' : 'جاري تسجيل الدخول...');
    Xtream.login(acc, function (err) {
      self.busy = false;
      UI.loading(false);
      if (err) {
        self.msg(Xtream.errorText(err));
        /* a failed attempt keeps the phone channel open for another try */
        if (Pair.enabled()) self.pairStatus('ready');
        return;
      }
      Store.setAccount(acc);
      Pair.stop();
      Xtream.clearCache();
      App.go('home', {}, { reset: true });
    });
  }
};

