      /* a movie / episode: the server often refuses the first try (or the list gave the wrong
         file type): try again from the same moment, with the file type the server gives */
      var me = this, p = this.p;
      this.retriedUrl = this.url;
      Player.release();          /* let the provider drop this screen's failed connection first */
      p.late = true;             /* Samsung: second try plays first, then jumps to the saved moment */
      this.center('buffer');
      var again = function () {
        if (App.current() !== 'player' || me.p !== p) return;
        p.startAt = me.time;
        me.start();
      };
      if (p.kind === 'movie' && p.item) {
        Xtream.getVodInfo(p.item.id, function (err, d) {
          var ext = d && d.movie_data && d.movie_data.container_extension;
          if (ext) p.item.ext = ext;
          setTimeout(again, 4000);
        });
      } else setTimeout(again, 4000);
      return;
    }
    this.center('');
    if (this.isLive()) {
      this.msg('تعذّر تشغيل هذه القناة حالياً', 'جرّب قناة أخرى أو غيّر صيغة البث من الإعدادات', detail);
    } else this.explainError(detail);
    this.showOSD(true);
  };

  /* why a movie / episode does not play, in words, with the TV's own error code underneath
     and what the provider answers for this file (http status) */
  S.explainError = function (detail) {
    var self = this, p = this.p, d = String(detail || ''), title = 'تعذّر تشغيل هذا المحتوى';
    var sub = 'تأكد من الاتصال أو جرّب لاحقاً';
    if (/NOT_SUPPORTED|UNSUPPORTED|CODEC|FORMAT/i.test(d)) sub = 'صيغة الصوت أو الصورة في هذا الملف غير مدعومة على هذه الشاشة';
    this.msg(title, sub, d);
    Player.release();
    setTimeout(function () { self.checkUrl(self.url, onAnswer); }, 3000);
    function onAnswer(st, body) {
      if (App.current() !== 'player' || self.p !== p || Player.state() !== 'error') return;
      var code = d + ' · ' + (st ? 'http ' + st : 'no answer');
      var said = st >= 400 && body ? body.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 40) : '';
      if (said) code += ' · ' + said;
      var busy = st === 403 || st === 429 || st === 458 || st === 509 || /max|limit|connection|exceed/i.test(said);
      if (st === 404) sub = 'الملف غير موجود عند المزوّد — جرّب حلقة أخرى أو لاحقاً';
      else if (st === 200 || st === 206) sub = 'الملف متاح عند المزوّد لكن مشغّل الشاشة لم يفتحه — اخرج من التطبيق وادخل مرة أخرى ثم جرّب';
      else if (busy) sub = 'المزوّد رفض التشغيل — غالباً الاشتراك مستخدم على جهاز أو تطبيق آخر';
      else if (!st) sub = 'المزوّد لم يرد على هذا الملف — تأكد من الإنترنت أو جرّب لاحقاً';
      self.msg(title, sub, code);
      var acc = Xtream.account();
      if (!acc) return;
      Xtream.probe(acc, function (err, data) {
        if (App.current() !== 'player' || self.p !== p || Player.state() !== 'error') return;
        if (err && err.code === 'expired') { self.msg(title, 'انتهى الاشتراك عند المزوّد', code); return; }
        var ui = data && data.user_info;
        var max = ui ? parseInt(ui.max_connections, 10) : 0, act = ui ? parseInt(ui.active_cons, 10) : 0;
        if (max > 0) code += ' · ' + act + '/' + max;
        /* busy only when the provider refused this screen too: when it served the file (200/206)
           the count is just this screen's own last try and the trouble is opening the file */
        if (max > 0 && act >= max && st !== 200 && st !== 206) self.waitFree(title, code, 0);
        else self.msg(title, sub, code);
      });
    }
  };

  /* asks the provider for the first two bytes of the file: only the answer (status) is kept */
  S.checkUrl = function (url, cb) {
    var done = false;
    function end(st, body) { if (done) return; done = true; cb(st || 0, body || ''); }
    try {
      var x = new XMLHttpRequest();
      x.open('GET', url, true);
      try { x.setRequestHeader('Range', 'bytes=0-1'); } catch (e) {}
      x.timeout = 8000;
      x.onreadystatechange = function () {
        if (x.readyState === 2 && x.status && x.status < 400) { var st = x.status; try { x.abort(); } catch (e) {} end(st); }
        else if (x.readyState === 4) { var t = ''; try { t = String(x.responseText || '').slice(0, 300); } catch (e) {} end(x.status, t); }
      };
      x.onerror = function () { end(0); };
      x.ontimeout = function () { end(0); };
      x.send();
    } catch (e) { end(0); }
  };

  /* The subscription is full. Usually it is this TV's own previous video: the provider takes a
     few seconds to count it as stopped (one-screen subscriptions, when moving to the next episode).
     Wait for the place to free up and start by itself; say "another screen" only if it stays full. */
  /* The provider still counts an earlier playback as running (a screen switched off while
     playing stays "busy" at the provider for a few minutes). Wait here, up to 3 minutes,
     and start by itself the moment the subscription is free. */
  S.waitFree = function (title, d, n) {
    var self = this, p = this.p, acc = Xtream.account(), EVERY = 5000, MAX = 36;
    p.busyWaits = (p.busyWaits || 0) + (n === 0 ? 1 : 0);
    if (!acc || n >= MAX || p.busyWaits > 3) {
      self.msg(title, 'الاشتراك ما زال مستخدماً على شاشة أخرى — أوقف التشغيل عليها، أو انتظر دقيقتين بعد آخر تشغيل، ثم جرّب مرة أخرى', d);
      return;
    }
    var left = Math.round((MAX - n) * EVERY / 1000), mm = Math.floor(left / 60), ss = left % 60;
    self.msg('لحظات ويبدأ التشغيل…', 'اشتراكك يسمح بعدد محدود من الشاشات، والمزوّد ما زال يحسب تشغيلاً سابقاً (على هذا الجهاز أو جهاز آخر) — سيبدأ هنا تلقائياً فور تحرّره (انتظار حتى ' +
      mm + ':' + (ss < 10 ? '0' : '') + ss + ')', '');
    self.center('buffer');
    setTimeout(function () {
      if (App.current() !== 'player' || self.p !== p) return;
      Xtream.probe(acc, function (err, data) {
        if (App.current() !== 'player' || self.p !== p) return;
        var ui = data && data.user_info;
        var max = ui ? parseInt(ui.max_connections, 10) : 0, act = ui ? parseInt(ui.active_cons, 10) : 0;
        if (max > 0 && act >= max) { self.waitFree(title, d, n + 1); return; }
        p.startAt = self.time;
        self.start();
      });
    }, EVERY);
  };

  /* movie or episode reached the end */
  S.finished = function () {
    this.save(true);
    if (this.p.kind === 'episode' && Store.getSettings().autoNext) {
      var n = this.nextEp(1);
      if (n) {
        UI.toast('تشغيل الحلقة التالية...');
        this.p.seasonIdx = n.s; this.p.epIdx = n.e; this.p.startAt = 0;
        this.start();
        return;
      }
    }
    this.exit();
  };

  S.nextEp = function (d) {
    var ss = this.p.seasons, s = this.p.seasonIdx, e = this.p.epIdx + d;
    if (e >= 0 && e < ss[s].episodes.length) return { s: s, e: e };
    if (d > 0 && s + 1 < ss.length && ss[s + 1].episodes.length) return { s: s + 1, e: 0 };
    if (d < 0 && s - 1 >= 0 && ss[s - 1].episodes.length) return { s: s - 1, e: ss[s - 1].episodes.length - 1 };
    return null;
  };

  /* remember the position of movies / episodes */
  S.save = function (ended) {
    var p = this.p;
    if (!p || this.isLive()) return;
    var pos = Player.getTime() || this.time;
    var dur = Player.getDuration() || this.dur;
    if (!dur) return;
    if (!ended && pos < 5000) return;
    var done = ended || pos > dur * 0.93;
    if (p.kind === 'movie') {
      Store.setHist('m:' + p.item.id, { pos: done ? 0 : pos, dur: dur, done: done, item: Store.slim(p.item) });
    } else {
      var ep = this.episode();
      Store.setHist('e:' + ep.id, { pos: done ? 0 : pos, dur: dur, done: done });
      Store.setHist('s:' + p.series.id, { episodeId: ep.id, season: ep.season, num: ep.num, item: Store.slim(p.series) });
    }
  };

  S.exit = function () {
    this.reportLive();
    this.save();
    this.clearTimers();
    Player.stop();
    var p = this.p;
    if (p.kind === 'live') App.back({ index: p.index });
    else if (p.kind === 'episode') App.back({ seasonIdx: p.seasonIdx, epIdx: p.epIdx });
    else App.back();
  };

  /* TV app hidden (Home button / source change) and shown again */
  S.visibility = function (hidden) {
    if (hidden) {
      this.reportLive();
      this.save();
      this.resumeAt = Player.getTime() || this.time;
      clearInterval(this.saveTimer);
      Player.stop();
    } else if (this.p) {
      if (!this.isLive()) this.p.startAt = this.resumeAt || 0;
      this.start();
    }
  };

  /* ---------------- live helpers ---------------- */
  /* remote diagnostics: how fast the channel opened and how often it froze */
  S.reportLive = function () {
    if (!this.p || !this.isLive()) return;
    var st = Player.stats();
    if (!st.live || st.secs < 8) return;
    S.liveReports = (S.liveReports || 0) + 1;
    if (S.liveReports > 12) return;
    Diag.send('live' + S.liveReports, 'fmt=' + this.fmt + ' start=' + st.startMs + 'ms stalls=' + st.stalls +
      ' frozen=' + Math.round(st.stallMs / 1000) + 's of ' + st.secs + 's');
  };

  S.zapTo = function (i) {
    var n = this.p.list.length;
    if (!n) return;
    this.reportLive();
    this.p.index = (i + n) % n;
    this.start();
  };

  S.loadEpg = function () {
    var self = this, ch = this.channel();
    Xtream.getShortEpg(ch.id, function (err, list) {
      if (!self.p || !self.isLive() || self.channel().id !== ch.id) return;
      self.epg = err ? [] : list;
      self.renderBottom();
    });
  };

  S.openZap = function () {
    this.zapOpen = true;
    U.addClass(U.$('pl-zap'), 'open');
    U.$('pl-zap-head').innerHTML = '<b>' + U.esc(this.p.catName || 'القنوات') + '</b><span>' + this.p.list.length + ' قناة</span>';
    this.zap.setActive(true);
    this.zap.setItems(this.p.list, this.p.index);
    this.hideOSD();
    this.armZap();
  };

  S.closeZap = function (instant) {
    this.zapOpen = false;
    clearTimeout(this.zapTimer);
    U.removeClass(U.$('pl-zap'), 'open');
  };

  S.armZap = function () {
    var self = this;
    clearTimeout(this.zapTimer);
    this.zapTimer = setTimeout(function () { self.closeZap(); }, 12000);
  };

  S.numKey = function (d) {
    var self = this;
    this.numBuf = (this.numBuf + d).substr(-4);
    var el = U.$('pl-num');
    el.innerHTML = this.numBuf;
    el.style.display = 'block';
    clearTimeout(this.numTimer);
    this.numTimer = setTimeout(function () {
      var buf = self.numBuf;
      self.numBuf = '';
      el.style.display = 'none';
      var l = self.p.list;
      for (var i = 0; i < l.length; i++) {
        if (String(l[i].num) === buf) { self.zapTo(i); return; }
      }
      UI.toast('القناة رقم ' + buf + ' غير موجودة في هذه القائمة');
    }, 1600);
  };

  /* ---------------- VOD seeking ---------------- */
  /* left / right move the position; the jump happens by itself a moment
     after the last press (holding the key moves further before jumping) */
  S.seekBy = function (sec, fixed, fast) {
    var self = this;
    var dur = Player.getDuration() || this.dur;
    if (!dur) return;
    var first = this.seekTarget === null;
    var base = first ? (Player.getTime() || this.time) : this.seekTarget;
    /* holding the key moves faster: 10 s, then 30 s, then 60 s steps */
    var dir = sec > 0 ? 1 : -1;
    if (first || dir !== this.seekDir) this.seekSteps = 0;
    this.seekDir = dir;
    this.seekSteps++;
    var n = this.seekSteps;
    /* on the progress bar it speeds up more: 10 s, 30 s, 1 min, 2 min, then 5 min steps */
    var step = fixed || Math.abs(sec) > 10 ? Math.abs(sec) :
      fast ? (n > 25 ? 300 : (n > 15 ? 120 : (n > 8 ? 60 : (n > 3 ? 30 : 10)))) : (n > 12 ? 60 : (n > 5 ? 30 : 10));
    this.seekTarget = U.clamp(base + dir * step * 1000, 0, dur - 3000);
    this.showOSD(true);
    this.updateProgress(this.seekTarget);
    this.seekHint();
    clearTimeout(this.seekTimer);
    this.seekTimer = setTimeout(function () { self.commitSeek(); }, fast ? 1200 : 800);
  };

  S.seekHint = function () {
    var hint = U.$('pl-keyhint');
    if (!hint || this.seekTarget === null) return;
    var d = Math.round((this.seekTarget - (Player.getTime() || this.time)) / 1000);
    var txt = (d >= 0 ? '+' : '-') + U.fmtTime(Math.abs(d) * 1000);
    hint.innerHTML = (d >= 0 ? 'تقديم إلى ' : 'ترجيع إلى ') + U.fmtTime(this.seekTarget) +
      ' <span class="seek-delta" dir="ltr">(' + txt + ')</span>';
  };

  S.commitSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    var t = this.seekTarget;
    this.seekTarget = null;
    this.time = t;
    Player.seekTo(t);
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };

  S.cancelSeek = function () {
    if (this.seekTarget === null) return false;
    clearTimeout(this.seekTimer);
    this.seekTarget = null;
    this.updateProgress();
    this.drawBar();
    this.showOSD();
    return true;
  };


  /* ---------------- OSD rendering ---------------- */
  S.renderOSD = function () {
    var p = this.p, h = '';
    if (p.kind === 'live') {
      var ch = this.channel();
      var fav = Store.isFav('live', ch.id) ? '<span class="pl-fav">' + STAR + '</span>' : '';
      h = '<div class="pl-ch"><span class="pl-chnum">' + U.esc(ch.num || (p.index + 1)) + '</span>' +
        U.img(ch.icon, ch.name, 'pl-logo') +
        '<div><div class="pl-title">' + U.esc(ch.name) + fav + '</div>' +
        '<div class="pl-subtitle">' + U.esc(p.catName || '') + '</div></div></div>';
    } else if (p.kind === 'movie') {
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.item.name) + '</div>' +
        '<div class="pl-subtitle">فيلم</div></div></div>';
    } else {
      var ep = this.episode(), s = p.seasons[p.seasonIdx];
      h = '<div class="pl-ch"><div><div class="pl-title">' + U.esc(p.series.name) + '</div>' +
        '<div class="pl-subtitle">الموسم ' + U.esc(s.num) + ' · الحلقة ' + U.esc(ep.num) +
        (ep.title ? ' — ' + U.esc(ep.title) : '') + '</div></div></div>';
    }
    if (p.kind === 'live') {
      U.$('pl-top').innerHTML = h + '<div class="clock">' + UI.clockText() + '</div>';
    } else {
      /* movies / episodes: round option buttons at the top */
      this.tools = this.vodTools();
      var t = '<div class="pl-tools">';
      for (var i = 0; i < this.tools.length; i++) {
        t += '<div class="pl-tool" data-t="' + i + '">' + this.tools[i].icon + '<span class="tl">' + U.esc(this.tools[i].label) + '</span></div>';
      }
      t += '<div class="clock">' + UI.clockText() + '</div></div>';
      U.$('pl-top').innerHTML = h + t;
    }
    this.renderBottom();
  };

  S.renderBottom = function () {
    var h = '';
    if (this.isLive()) {
      if (this.epg.length) {
        var now = this.epg[0], next = this.epg[1];
        var pct = now.end > now.start ? U.clamp((U.now() - now.start) / (now.end - now.start), 0, 1) : 0;
        h += '<div class="pl-epg"><div class="pl-epg-now">' +
          '<span class="chip now">الآن</span><b>' + U.esc(now.title) + '</b>' +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(now.start)) + ' - ' + U.fmtClock(new Date(now.end)) + '</span></div>' +
          '<div class="bar" dir="ltr"><i style="width:' + Math.round(pct * 100) + '%"></i></div>';
        if (next) h += '<div class="pl-epg-next"><span class="chip">التالي</span>' + U.esc(next.title) +
          '<span class="pl-epg-time">' + U.fmtClock(new Date(next.start)) + '</span></div>';
        h += '</div>';
      }
      var fav = Store.isFav('live', this.channel().id);
      this.barItems = [
        { a: 'channels', icon: ICON.list, label: 'القنوات' },
        { a: 'audio', icon: ICON.audio, label: 'الصوت' },
        { a: 'subs', icon: ICON.subs, label: 'الترجمة', dot: 'yellow' },
        { a: 'aspect', icon: ICON.aspect, label: 'أبعاد الشاشة', dot: 'blue' },
        { a: 'fav', icon: STAR, label: fav ? 'إزالة من المفضلة' : 'إضافة للمفضلة', dot: 'red' }
      ];
      h += this.barHtml();
    } else {
      h += '<div class="pl-progress" dir="ltr">' +
        '<span class="pl-cur" id="pl-cur">00:00</span>' +
        '<div class="bar big"><i id="pl-fill"></i><b id="pl-knob"></b></div>' +
        '<span class="pl-dur" id="pl-dur">--:--</span></div>';
      /* media buttons, laid out left-to-right like every player */
      this.ctrls = this.vodCtrls();
      h += '<div class="pl-ctrls" dir="ltr">';
      for (var c = 0; c < this.ctrls.length; c++) {
        var b = this.ctrls[c];
        h += '<div class="pl-c ' + b.cls + '" data-c="' + c + '">' + b.icon + (b.ten ? '<b>10</b>' : '') +
          '<span class="tl">' + U.esc(b.label) + '</span></div>';
      }
      h += '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
      this.barItems = [];
    }
    U.$('pl-bottom').innerHTML = h;
    if (this.isLive() && this.barIdx >= this.barItems.length) this.barIdx = this.barItems.length - 1;
    this.drawBar();
    this.updateProgress();
  };

  /* ---------------- bottom button bar (reach it with the arrows) ---------------- */
  S.barHtml = function () {
    var h = '<div class="pl-bar">';
    for (var i = 0; i < this.barItems.length; i++) {
      var b = this.barItems[i];
      h += '<div class="pl-btn" data-b="' + i + '">' + b.icon + '<span>' + U.esc(b.label) + '</span>' +
        (b.dot ? '<i class="dot ' + b.dot + '"></i>' : '') + '</div>';
    }
    return h + '</div><div class="pl-keyhint" id="pl-keyhint"></div>';
  };

  S.drawBar = function () {
    if (!this.isLive()) { this.drawVod(); return; }
    var btns = U.$('pl-bottom').querySelectorAll('.pl-btn');
    for (var i = 0; i < btns.length; i++) U.toggleClass(btns[i], 'focused', i === this.barIdx);
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.barIdx >= 0) hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▲</span> رجوع';
    else if (this.isLive()) hint.innerHTML = '<span class="kb" dir="ltr">▲ ▼</span> تغيير القناة <span class="kb" dir="ltr">◀ ▶</span> الخيارات <span class="kb">OK</span> قائمة القنوات';
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ترجيع / تقديم <span class="kb">OK</span> إيقاف / تشغيل <span class="kb">▼</span> الخيارات';
    if (this.barIdx < 0 && this.seekTarget !== null) this.seekHint();
  };

  S.enterBar = function () {
    this.barIdx = 0;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.leaveBar = function (hide) {
    this.barIdx = -1;
    this.vz = null;
    clearTimeout(this.barTimer);
    this.drawBar();
    if (hide) this.hideOSD(); else this.showOSD();
  };

  /* drop the focus after 10 s without a key */
  S.armBar = function () {
    var self = this;
    clearTimeout(this.barTimer);
    this.barTimer = setTimeout(function () { if (!UI.modal()) self.leaveBar(true); else self.armBar(); }, 10000);
  };

  /* a menu opened from the bar closed: come back to the bar */
  S.menuClosed = function () {
    if (this.barIdx < 0 || App.current() !== 'player') return;
    this.showOSD(true);
    this.drawBar();
    this.armBar();
  };

  S.barKey = function (k) {
    var n = this.barItems.length;
    this.armBar();
    switch (k) {
      case 'left': if (this.barIdx < n - 1) { this.barIdx++; this.drawBar(); } return true;
      case 'right': if (this.barIdx > 0) { this.barIdx--; this.drawBar(); } return true;
      case 'enter': this.barAction(this.barItems[this.barIdx].a); return true;
      case 'up': case 'back': this.leaveBar(false); return true;
      case 'down': if (this.isLive()) this.leaveBar(false); return true;
    }
    return false;
  };

  S.barAction = function (a) {
    switch (a) {
      case 'toggle':
        if (Player.state() === 'error') { this.p.startAt = this.time; this.start(); break; }
        Player.toggle(); this.showOSD(true);
        break;
      case 'prevEp': this.changeEpisode(-1); break;
      case 'nextEp': this.changeEpisode(1); break;
      case 'audio': this.audioMenu(); break;
      case 'subs': this.subsMenu(); break;
      case 'speed': this.speedMenu(); break;
      case 'aspect': this.aspectMenu(); break;
      case 'channels': this.barIdx = -1; this.openZap(); break;
      case 'fav':
        var on = Store.toggleFav(this.channel());
        UI.toast(on ? 'تمت إضافة القناة للمفضلة' : 'تمت إزالة القناة من المفضلة');
        this.renderOSD(); this.showOSD(true);
        break;
    }
  };

  S.changeEpisode = function (d) {
    if (this.p.kind !== 'episode') return;
    var n = this.nextEp(d);
    if (!n) { UI.toast(d > 0 ? 'هذه آخر حلقة' : 'هذه أول حلقة'); return; }
    this.save();
    this.p.seasonIdx = n.s; this.p.epIdx = n.e;
    var h = Store.getHist('e:' + this.episode().id);
    this.p.startAt = h && !h.done && h.pos > 30000 ? h.pos : 0;
    var keep = this.barIdx, kz = this.vz;
