  /* ================= movies / episodes: top options + media buttons ================= */
  S.vodTools = function () {
    var t = [];
    if (this.p.kind === 'episode') t.push({ a: 'episodes', icon: ICON.eps, label: 'الحلقات' });
    t.push({ a: 'audio', icon: ICON.audio, label: 'الصوت' });
    t.push({ a: 'subs', icon: ICON.subs, label: 'الترجمة' });
    if (Player.speedOk && Player.speedOk()) t.push({ a: 'speed', icon: ICON.speed, label: 'السرعة' });
    t.push({ a: 'aspect', icon: ICON.aspect, label: 'أبعاد الشاشة' });
    return t;
  };

  S.vodCtrls = function () {
    var ep = this.p.kind === 'episode', c = [];
    if (ep) c.push({ a: 'prevEp', icon: ICON.prev, cls: 'sm', label: 'الحلقة السابقة' });
    c.push({ a: 'rw10', icon: ICON.replay, cls: 'md', ten: true, label: 'رجوع 10 ث' });
    c.push({ a: 'toggle', icon: this.paused ? PLAY : PAUSE, cls: 'lg', label: this.paused ? 'تشغيل' : 'إيقاف مؤقت' });
    c.push({ a: 'ff10', icon: ICON.replay, cls: 'md ff', ten: true, label: 'تقديم 10 ث' });
    if (ep) c.push({ a: 'nextEp', icon: ICON.next, cls: 'sm', label: 'الحلقة التالية' });
    return c;
  };

  S.playIndex = function () {
    for (var i = 0; i < (this.ctrls || []).length; i++) if (this.ctrls[i].a === 'toggle') return i;
    return 0;
  };

  S.drawVod = function () {
    var i, el = U.$('pl-top').querySelectorAll('.pl-tool');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'top' && i === this.vt);
    el = U.$('pl-bottom').querySelectorAll('.pl-c');
    for (i = 0; i < el.length; i++) U.toggleClass(el[i], 'focused', this.vz === 'ctrl' && i === this.vc);
    var pg = U.$('pl-bottom').querySelector('.pl-progress');
    if (pg) U.toggleClass(pg, 'focused', this.vz === 'bar');
    var hint = U.$('pl-keyhint');
    if (!hint) return;
    if (this.seekTarget !== null) { this.seekHint(); return; }
    if (this.vz === 'bar') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ترجيع / تقديم (اضغط باستمرار للأسرع) <span class="kb">OK</span> إيقاف / تشغيل <span class="kb">▼</span> أزرار التشغيل <span class="kb">▲</span> الخيارات';
    else if (this.vz === 'ctrl') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▲</span> شريط التقديم';
    else if (this.vz === 'top') hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> تنقّل <span class="kb">OK</span> اختيار <span class="kb">▼</span> شريط التقديم';
    else hint.innerHTML = '<span class="kb" dir="ltr">◀ ▶</span> ترجيع / تقديم <span class="kb">OK</span> إيقاف / تشغيل <span class="kb">▼</span> أزرار التشغيل <span class="kb">▲</span> شريط التقديم' +
      (this.p.kind === 'episode' ? ' <span class="kb green"></span> الحلقات' : '');
  };

  S.enterVod = function (z) {
    this.vz = z;
    this.barIdx = 0;
    if (z === 'ctrl') this.vc = this.playIndex();
    else this.vt = 0;
    this.showOSD(true);
    this.drawVod();
    this.armBar();
  };

  S.vodKey = function (k) {
    this.armBar();
    if (this.vz === 'ctrl') {
      var n = this.ctrls.length;
      if (k === 'left') { if (this.vc > 0) { this.vc--; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vc < n - 1) { this.vc++; this.drawVod(); } return true; }
      if (k === 'up') { this.vz = 'bar'; this.drawVod(); return true; }
      if (k === 'down' || k === 'back') { this.leaveBar(k === 'down'); return true; }
      if (k === 'enter') { this.vodAction(this.ctrls[this.vc].a); return true; }
    } else if (this.vz === 'bar') {
      /* the progress bar: left / right move along it, the jump happens a moment after the last press */
      if (k === 'right') { this.seekBy(10, false, true); return true; }
      if (k === 'left') { this.seekBy(-10, false, true); return true; }
      if (k === 'up' || k === 'down') {
        this.commitSeek();
        if (k === 'up') { this.vz = 'top'; this.vt = this.vt || 0; }
        else { this.vz = 'ctrl'; if (this.vc === undefined || this.vc >= this.ctrls.length) this.vc = this.playIndex(); }
        this.drawVod();
        return true;
      }
      if (k === 'enter') {
        if (!this.commitSeek()) { Player.toggle(); this.showOSD(true); }
        this.drawVod();
        return true;
      }
      if (k === 'back') { if (this.cancelSeek()) this.drawVod(); else this.leaveBar(false); return true; }
    } else if (this.vz === 'top') {
      var m = this.tools.length;
      if (k === 'left') { if (this.vt < m - 1) { this.vt++; this.drawVod(); } return true; }
      if (k === 'right') { if (this.vt > 0) { this.vt--; this.drawVod(); } return true; }
      if (k === 'down') { this.vz = 'bar'; this.drawVod(); return true; }
      if (k === 'up' || k === 'back') { this.leaveBar(false); return true; }
      if (k === 'enter') { this.vodAction(this.tools[this.vt].a); return true; }
    }
    return false;
  };

  S.vodAction = function (a) {
    if (a === 'rw10') { this.seekBy(-10, true); return; }
    if (a === 'ff10') { this.seekBy(10, true); return; }
    if (a === 'episodes') { this.openEps(); return; }
    this.barAction(a);
  };

  /* ================= episodes panel (inside the player) ================= */
  S.openEps = function () {
    if (this.p.kind !== 'episode') return;
    var self = this;
    if (!this.epsList) {
      this.epsList = new VList(U.$('eps-list'), {
        rows: 5, extra: 1, rowClass: 'eprow',
        render: function (ep, i) { return self.renderEp(ep, i); }
      });
