      ['تاريخ الانتهاء', exp > 0 ? U.fmtDate(exp) : 'غير محدود'],
      ['تاريخ الإنشاء', created > 0 ? U.fmtDate(created) : '-'],
      ['الأجهزة المتصلة', (u.active_cons || 0) + ' / ' + (u.max_connections || '-')],
      ['حساب تجريبي', String(u.is_trial) === '1' ? 'نعم' : 'لا'],
      ['السيرفر', acc.server || '-'],
      ['المنطقة الزمنية', s.timezone || '-']
    ];
    var h = '<h2>بيانات الاشتراك</h2>';
    for (var i = 0; i < rows.length; i++) {
      var ltr = i === 0 || i === 6 ? ' dir="ltr"' : '';
      h += '<div class="acc-row"><span>' + rows[i][0] + '</span><b' + ltr + '>' + U.esc(rows[i][1]) + '</b></div>';
    }
    U.$('set-account').innerHTML = h;
  },

  action: function () {
    var id = this.rows()[this.idx].id;
    var s = Store.getSettings();
    if (id === 'fmt') Store.setSetting('liveFormat', s.liveFormat === 'm3u8' ? 'ts' : 'm3u8');
    else if (id === 'engine') Player.cycleEngine();
    else if (id === 'aspect') { this.aspectMenu(); return; }
    else if (id === 'subs') { var ms = this; SubStyle.menu(function () { ms.draw(); }); return; }
    else if (id === 'next') Store.setSetting('autoNext', !s.autoNext);
    else if (id === 'sort') {
      /* newest first → oldest first → as on the server → newest first */
      if (s.sort === 'server') { Store.setSetting('sort', 'new'); Store.setSetting('sortDir', 'new'); }
      else if (s.sortDir === 'old') Store.setSetting('sort', 'server');
      else Store.setSetting('sortDir', 'old');
      UI.toast('سيظهر الترتيب الجديد عند فتح القسم');
    }
    else if (id === 'news') { this.newsMenu(); return; }
    else if (id === 'clock') { Store.setSetting('clock24', !s.clock24); UI.tickClock(); }
    else if (id === 'refresh') { Xtream.clearCache(); UI.toast('سيتم تحميل القوائم من جديد'); }
    else if (id === 'playlists') { App.go('playlists', {}); return; }
    else if (id === 'pin') { var me = this; Parental.menu(function () { me.draw(); }); return; }
    else if (id === 'hidden') { var me2 = this; Parental.hiddenMenu(function () { me2.draw(); }); return; }
    else if (id === 'updates') { var self = this; OTA.menu(function () { self.draw(); }); return; }
    else if (id === 'logout') {
      UI.confirm({
        title: 'تسجيل الخروج؟', text: 'سيتم حذف كل قوائم التشغيل من هذا الجهاز (المفضلة تبقى محفوظة).',
        buttons: [{ label: 'تسجيل الخروج', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }],
        index: 1,
        onSelect: function (v) {
          if (v !== 'yes') return;
          Player.stop();
          Store.clearPlaylists();
          Xtream.clearCache();
          App.go('login', {}, { reset: true });
        }
      });
      return;
    }
    this.draw();
  },

  newsMenu: function () {
    var self = this, cur = Store.getSettings().news, items = [];
    for (var i = 0; i < News.KEYS.length; i++) {
      var k = News.KEYS[i];
      items.push({ label: 'أخبار ' + News.SOURCES[k].name, value: k, selected: k === cur });
    }
    items.push({ label: 'إيقاف شريط الأخبار', value: 'off', selected: cur === 'off' });
    UI.menu({
      title: 'شريط الأخبار', items: items,
      onSelect: function (v) { if (v) Store.setSetting('news', v); self.draw(); }
    });
  },

  aspectMenu: function () {
    var self = this, cur = Player.aspectKey(), list = Player.aspectList(), items = [];
    for (var i = 0; i < list.length; i++) {
      items.push({ label: list[i].name, sub: list[i].desc, value: list[i].key, selected: list[i].key === cur });
    }
    UI.menu({
      title: 'أبعاد الشاشة', items: items,
      onSelect: function (v) { if (v !== null) Player.setAspect(v); self.draw(); }
    });
  },

  onKey: function (k) {
    var n = this.rows().length;
    if (k === 'up' && this.idx > 0) { this.idx--; this.draw(); }
    else if (k === 'down' && this.idx < n - 1) { this.idx++; this.draw(); }
    else if (k === 'enter') this.action();
    else if (k === 'back') App.back();
  }
};

/* ==========================================================================
   Playlists screen — several Xtream subscriptions on one TV.
   Shows every saved playlist with a live check (works / expired / not
   working), lets you switch to another one or delete one, and adds new
   playlists from the phone by scanning the QR code (or by typing them).
   ========================================================================== */
Screens.playlists = {
  idx: 0,
  status: {},             /* playlist id -> {cls, text} */
  note: '',

  STATUS: {
    connecting: 'جاري تجهيز الرمز...',
    ready: 'في انتظار الجوال...',
    offline: 'خدمة الربط غير متاحة حالياً',
    received: 'تم استلام البيانات ✓'
  },

  show: function (params) {
    this.params = params || {};
    this.note = this.params.message || '';
    this.status = {};
    var act = Store.activePlaylist(), list = Store.getPlaylists();
    this.idx = 0;
    for (var i = 0; i < list.length; i++) if (act && list[i].id === act.id) this.idx = i;
    this.draw();
    this.checkAll();
    this.startPairing();
  },

  resume: function (result) {
    if (result && result.added) {
      var list = Store.getPlaylists(), added = null;
      for (var i = 0; i < list.length; i++) if (list[i].id === result.added) { this.idx = i; added = list[i]; }
      /* a name the user knows it by ("البيت", "اشتراك الرياضة") instead of the server's address */
      var self = this;
      if (added) setTimeout(function () { if (App.current() === 'playlists') self.rename(added, true); }, 350);
    }
    this.draw();
    this.checkAll();
    this.startPairing();
  },

  hide: function () { Pair.stop(); },

  visibility: function (hidden) {
    if (hidden) Pair.stop();
    else this.startPairing();
  },

  rows: function () { return Store.getPlaylists().concat([{ add: true }]); },

  /* ---------------- drawing ---------------- */
  draw: function () {
    var rows = this.rows(), act = Store.activePlaylist(), h = '';
    if (this.idx >= rows.length) this.idx = rows.length - 1;
    if (this.note) h += '<div class="pls-note">' + U.esc(this.note) + '</div>';
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i], f = i === this.idx ? ' focused' : '';
      if (r.add) {
        h += '<div class="plsrow add' + f + '" data-i="' + i + '"><div class="pls-info"><b>＋  إضافة قائمة يدوياً</b>' +
          '<span class="rtl">بيانات Xtream أو رابط قائمة M3U</span></div></div>';
        continue;
      }
      var cur = act && act.id === r.id;
      var st = this.status[r.id] || { cls: 'wait', text: '' };
      h += '<div class="plsrow' + f + (cur ? ' cur' : '') + '" data-i="' + i + '">' +
        '<div class="pls-info"><b>' + U.esc(r.name || 'قائمة ' + (i + 1)) + '</b>' +
        '<span>' + (r.kind === 'm3u' ? 'M3U  ·  ' + U.esc(M3U.hostOf(r.url)) + (r.epg ? '  ·  دليل برامج' : '')
          : U.esc(r.username) + '  ·  ' + U.esc(r.server)) + '</span></div>' +
        '<div class="pls-badges">' + (cur ? '<span class="pls-cur">قيد التشغيل</span>' : '') +
        (st.text ? '<span class="pls-st ' + st.cls + '">' + U.esc(st.text) + '</span>' : '') + '</div></div>';
    }
    var el = U.$('pls-list');
    el.innerHTML = h;
    var n = rows.length - 1;
    U.$('pls-count').innerHTML = n === 1 ? 'قائمة واحدة' : n === 2 ? 'قائمتان' : n + ' قوائم';
    /* keep the focused row visible */
    var row = el.querySelector('.plsrow.focused');
    if (row) {
      if (row.offsetTop + row.offsetHeight > el.scrollTop + el.clientHeight) el.scrollTop = row.offsetTop + row.offsetHeight - el.clientHeight;
      if (row.offsetTop < el.scrollTop) el.scrollTop = row.offsetTop;
    }
  },

  /* ---------------- checking each playlist ---------------- */
  classify: function (err, data) {
    if (err) {
      if (err.code === 'auth') return { cls: 'bad', text: 'بيانات الدخول غير صحيحة' };
      if (err.code === 'expired') return { cls: 'bad', text: 'الاشتراك منتهي' };
      if (err.code === 'banned' || err.code === 'disabled') return { cls: 'bad', text: 'الاشتراك موقوف' };
      return { cls: 'bad', text: 'لا يعمل حالياً' };
    }
    if (data && data.kind === 'm3u') {
      var c = data.counts, parts = [];
      if (c.live) parts.push(c.live + ' قناة');
      if (c.vod) parts.push(c.vod + ' فيلم');
      if (c.series) parts.push(c.series + ' مسلسل');
      return { cls: 'ok', text: '✓ يعمل · ' + parts.join(' · ') };
    }
    var exp = parseInt(data && data.user_info && data.user_info.exp_date, 10);
    if (exp > 0) {
      var days = Math.ceil((exp * 1000 - U.now()) / 86400000);
      return { cls: days <= 5 ? 'warn' : 'ok', text: '✓ يعمل · ' + (days <= 0 ? 'ينتهي اليوم' : days === 1 ? 'باقي يوم' : days === 2 ? 'باقي يومان' : 'باقي ' + days + (days <= 10 ? ' أيام' : ' يوماً')) };
    }
    return { cls: 'ok', text: '✓ يعمل' };
  },

  checkOne: function (p) {
    var self = this;
    this.status[p.id] = { cls: 'wait', text: 'جاري الفحص...' };
    Xtream.probe(p, function (err, data) {
      self.status[p.id] = self.classify(err, data);
      if (App.current() === 'playlists') self.draw();
    });
  },

  checkAll: function () {
    var list = Store.getPlaylists();
    for (var i = 0; i < list.length; i++) this.checkOne(list[i]);
    this.draw();
  },

  /* ---------------- adding from the phone (QR) ---------------- */
  startPairing: function () {
    var self = this, card = U.$('pls-qr');
    if (!Pair.enabled()) { card.style.display = 'none'; return; }
    card.style.display = '';
    var s = Pair.start({
      onStatus: function (st) { self.pairStatus(st); },
      onCredentials: function (c) { self.fromPhone(c); }
    });
    try { QR.drawCanvas(U.$('pls-qr-canvas'), s.url, { ecl: 'M', px: 300, margin: 3 }); }
    catch (e) { card.style.display = 'none'; }
  },

  pairStatus: function (st) {
    var el = U.$('pls-qr-status');
    el.className = 'qr-status ' + st;
    el.querySelector('span').innerHTML = U.esc(this.STATUS[st] || '');
  },

  fromPhone: function (c) {
    var self = this;
    var p = Xtream.parseServer(c.server || ''), acc;
    if (c.kind === 'm3u' || (!c.username && Xtream.m3uLink(c.url || c.server))) {
      acc = { kind: 'm3u', url: Xtream.m3uLink(c.url || c.server), epg: c.epg || '' };
      if (!acc.url) { UI.toast('الرابط غير صالح، حاول مرة أخرى'); this.startPairing(); return; }
      return this.addFromPhone(acc);
    }
    acc = {
      server: p.server || c.server,
      username: String(c.username || p.username || '').replace(/^\s+|\s+$/g, ''),
      password: String(c.password || p.password || '').replace(/^\s+|\s+$/g, '')
    };
    if (!acc.server || !acc.username || !acc.password) { UI.toast('البيانات ناقصة، حاول مرة أخرى'); this.startPairing(); return; }
    this.addFromPhone(acc);
  },

  addFromPhone: function (acc) {
    var self = this;
    UI.loading(true, 'جاري التحقق من قائمة التشغيل...');
    Xtream.probe(acc, function (err, data) {
      UI.loading(false);
      if (err && /^(auth|notlist|empty)$/.test(err.code)) {
        UI.toast(Xtream.errorText(err));
        self.startPairing();
        return;
      }
      var pl = Store.savePlaylist(acc);
      self.status[pl.id] = self.classify(err, data);
      var list = Store.getPlaylists();
      for (var i = 0; i < list.length; i++) if (list[i].id === pl.id) self.idx = i;
      self.note = '';
      self.draw();
      UI.toast(err ? 'تمت إضافة القائمة لكنها لا تعمل حالياً' : 'تمت إضافة قائمة التشغيل ✓');
      /* a fresh code, ready for one more */
      setTimeout(function () { if (App.current() === 'playlists') self.startPairing(); }, 2500);
    });
  },

  /* ---------------- actions ---------------- */
  action: function () {
    var self = this, r = this.rows()[this.idx];
    if (!r) return;
    if (r.add) { App.go('login', { add: true }); return; }
    var act = Store.activePlaylist(), cur = act && act.id === r.id, items = [];
    if (!cur) items.push({ label: 'تشغيل هذه القائمة', value: 'use' });
    items.push({ label: 'فحص الاتصال', value: 'check' });
    items.push({ label: 'تغيير الاسم', value: 'name' });
    items.push({ label: r.kind === 'm3u' ? 'تعديل الرابط ودليل البرامج' : 'تعديل البيانات', value: 'edit' });
    items.push({ label: 'حذف القائمة', value: 'del' });
    UI.menu({
      title: r.name || 'قائمة التشغيل', items: items,
      onSelect: function (v) {
        if (v === 'use') self.use(r);
        else if (v === 'check') { self.checkOne(r); self.draw(); }
        else if (v === 'edit') App.go('login', { add: true, preset: r });
        else if (v === 'name') setTimeout(function () { self.rename(r); }, 120);
        else if (v === 'del') self.remove(r);
      }
    });
  },

  rename: function (p, fresh) {
    var self = this;
    UI.prompt({
      title: fresh ? 'اسم القائمة الجديدة' : 'تغيير اسم القائمة',
      text: 'اسم تعرف به هذه القائمة، مثل «البيت» أو «اشتراك الرياضة».',
      value: p.name || '', placeholder: 'اسم القائمة',
      onDone: function (v) {
        if (!v) return;
        Store.renamePlaylist(p.id, v);
        self.draw();
        UI.toast('تم حفظ الاسم ✓');
      }
    });
  },

  use: function (p) {
    Pair.stop();
    Store.usePlaylist(p.id);
    Xtream.clearCache();
    UI.toast('جاري التبديل إلى ' + (p.name || 'القائمة'));
    App.reconnect();
  },

  remove: function (p) {
    var self = this;
    UI.confirm({
      title: 'حذف «' + (p.name || 'القائمة') + '»؟',
      text: 'سيتم حذف هذه القائمة من الجهاز.',
      buttons: [{ label: 'حذف', value: 'yes', danger: true }, { label: 'إلغاء', value: 'no' }],
      index: 1,
      onSelect: function (v) {
        if (v !== 'yes') return;
        var before = Store.activePlaylist();
        var now = Store.removePlaylist(p.id);
        UI.toast('تم حذف القائمة');
        if (!now) { Player.stop(); Xtream.clearCache(); App.go('login', {}, { reset: true }); return; }
        if (!before || before.id !== now.id) { Xtream.clearCache(); App.reconnect(); return; }
        self.draw();
      }
    });
  },

  onKey: function (k) {
    var n = this.rows().length;
    if (k === 'up' && this.idx > 0) { this.idx--; this.draw(); }
    else if (k === 'down' && this.idx < n - 1) { this.idx++; this.draw(); }
    else if (k === 'enter') this.action();
    else if (k === 'red') { var r = this.rows()[this.idx]; if (r && !r.add) this.remove(r); }
    else if (k === 'back') App.back();
  }
};

/* ==========================================================================
   Home on a phone / tablet: a big picture at the top from the user's own
   playlist (what he was watching, or the newest films and series): it slides
   by itself every few seconds and follows the finger. Then rows of posters:
   continue watching, newest films, newest series, favourites. The tab bar is
   the only menu.
   ========================================================================== */
Screens.t_home = {
  rowsData: {},
  feats: [],
  fi: 0,

  show: function () { this.render(); this.loadLatest(); },
  resume: function () { this.render(); this.loadLatest(); },
  hide: function () { clearInterval(this.turn); T.closeSheet(); },
  stopTurn: function () { clearInterval(this.turn); },

  /* ---------------- layout ---------------- */
  render: function () {
    var self = this, el = this.el;
    clearInterval(this.turn);
    var rows = this.rowsData = {
      cont: this.recentItems(),
      vodNew: this.latest.vod || [],
      seriesNew: this.latest.series || [],
      sagas: this.latest.sagas || [],
      top: this.latest.top || [],
      live: Parental.filter('live', Store.getFavs('live')),
      vod: Parental.filter('vod', Store.getFavs('vod')),
      series: Parental.filter('series', Store.getFavs('series'))
    };
    this.feats = this.pickFeatured();
    if (this.fi >= this.feats.length) this.fi = 0;
    var oldSc = el.querySelector('.th-scroll'), keepY = oldSc ? oldSc.scrollTop : 0;
    var pls = Store.getPlaylists(), act = Store.activePlaylist();
    var h = T.top({ brand: true, pill: pls.length > 1 && act ? { act: 'pls', label: act.name } : null, actions: ['search', 'settings'] });
    h += '<div class="t-scroll th-scroll">';
    h += '<section class="th-hero" id="th-hero"><div class="th-track" id="th-track"></div><div class="th-dots" id="th-dots"></div></section>';
    if (rows.cont.length) h += this.row('cont', 'تابع المشاهدة', rows.cont, 'poster');
    /* a playlist without films or series (channels only) simply has no such rows */
    if (!this.latest.vod || rows.vodNew.length) h += this.row('vodNew', 'أحدث الأفلام', rows.vodNew, 'poster', 'vod', !this.latest.vod);
    if (!this.latest.series || rows.seriesNew.length) h += this.row('seriesNew', 'أحدث المسلسلات', rows.seriesNew, 'poster', 'series', !this.latest.series);
    h += '<div id="th-extra">' + this.extras() + '</div>';
    if (rows.live.length) h += this.row('live', 'قنواتك المفضلة', rows.live, 'logo', 'fav-live');
    if (rows.vod.length) h += this.row('vod', 'أفلامك المفضلة', rows.vod, 'poster', 'fav-vod');
    if (rows.series.length) h += this.row('series', 'مسلسلاتك المفضلة', rows.series, 'poster', 'fav-series');
    h += '</div>' + T.tabs('home');
    el.innerHTML = h;
    el.className = 'screen t-screen th with-tabs';
    var sc = el.querySelector('.th-scroll'), top = el.querySelector('.t-top');
    sc.scrollTop = keepY;
    U.toggleClass(top, 'solid', keepY > 40);
    sc.addEventListener('scroll', function () { U.toggleClass(top, 'solid', sc.scrollTop > 40); });
    this.drawHero();
    T.bind(el, {
      pls: function () { App.go('playlists', {}); },
      hero: function (t) { self.heroAction(t.getAttribute('data-k'), parseInt(t.getAttribute('data-i'), 10)); },
      dot: function (t) { self.goSlide(parseInt(t.getAttribute('data-i'), 10)); self.startTurn(); },
      item: function (t) { self.open(t.getAttribute('data-k'), parseInt(t.getAttribute('data-i'), 10)); },
      more: function (t) {
        var w = t.getAttribute('data-k');
        if (w.indexOf('fav-') === 0) App.go('browse', { type: 'fav', favType: w.slice(4) }, { reset: true });
        else if (w === 'saga-all') App.go('browse', { type: 'vod', start: '__saga' }, { reset: true });
        else if (w === 'top-vod') App.go('browse', { type: 'vod', start: '__top' }, { reset: true });
        else T.goTab(w);
      }
    });
    if (!el.__held) {
      el.__held = true;
      T.holdable(el, '[data-act="item"]', function (t) {
        var k = t.getAttribute('data-k'), it = self.itemOf(k, parseInt(t.getAttribute('data-i'), 10));
        if (!it || k === 'cont' || k === 'sagas') return;
        T.favToast(Store.toggleFav(it));
        self.render();
      });
    }
    this.startTurn();
  },

  /* ---------------- data ---------------- */
  latest: {},
  loadLatest: function () {
    var self = this, acct = Store.acctKey();
    if (this.latest.acct !== acct) { this.latest = { acct: acct }; this.fi = 0; }
    ['vod', 'series'].forEach(function (type) {
      if (self.latest[type] || self.latest['busy' + type]) return;
      self.latest['busy' + type] = true;
      Xtream.getStreams(type, null, function (err, list) {
        if (err || !list) { self.latest[type] = []; }
        else {
          var withPic = [];
          for (var i = 0; i < list.length; i++) if (list[i].icon) withPic.push(list[i]);
          self.latest[type] = Xtream.newestFirst(Parental.filter(type, withPic)).slice(0, 24);
        }
        self.latest['busy' + type] = false;
        if (self.latest.acct !== Store.acctKey()) return;
        if (type === 'vod' && list && list.length) self.loadExtras();
        if (App.current() === 't_home' && self.latest.vod && self.latest.series) self.render();
      });
    });
  },

  /* the film series and the best rated films: worked out from the film list after it arrives,
     then put in their place without drawing the whole screen again */
  loadExtras: function () {
    var self = this, acct = this.latest.acct;
    Sagas.top('vod', function (e, top) {
      Sagas.get(function (e2, sagas) {
        if (self.latest.acct !== acct) return;
        self.latest.top = (top || []).slice(0, 24);
        self.latest.sagas = sagas || [];
        if (App.current() !== 't_home') return;
        self.rowsData.sagas = self.latest.sagas;
        self.rowsData.top = self.latest.top;
        var box = U.$('th-extra');
        if (box) box.innerHTML = self.extras();
      });
    });
  },
  extras: function () {
    var h = '', sg = this.rowsData.sagas || [], top = this.rowsData.top || [];
    if (sg.length) {
      h += '<section class="th-sec"><div class="th-sec-head"><h2>سلاسل الأفلام</h2>' +
        '<button type="button" class="t-link" data-act="more" data-k="saga-all">عرض الكل</button></div><div class="th-row r-saga">';
      for (var i = 0; i < sg.length && i < 20; i++) {
        h += '<button type="button" class="th-card" data-act="item" data-k="sagas" data-i="' + i + '">' + T.sagaPile(sg[i]) +
          '<b>' + T.esc(sg[i].name) + '</b><small>' + T.esc(Sagas.partsText(sg[i].count) + (sg[i].from ? ' · ' + Sagas.yearsText(sg[i]) : '')) + '</small></button>';
      }
      h += '</div></section>';
    }
    if (top.length) h += this.row('top', 'الأعلى تقييماً', top, 'poster', 'top-vod');
    return h;
  },

  /* films and series in progress, newest first (locked sections left out) */
  recentItems: function () {
    var r = Store.recent(20), out = [];
    for (var i = 0; i < r.length; i++) {
      var type = r[i].kind === 'vod' ? 'vod' : 'series';
      if (Parental.filter(type, [r[i].item]).length) out.push(r[i]);
    }
    return out;
  },

  /* the big picture: what was being watched first, then the newest films and series */
  pickFeatured: function () {
    var f = [], rows = this.rowsData, i;
    if (rows.cont[0]) f.push({ kind: rows.cont[0].kind, rec: rows.cont[0], item: rows.cont[0].item, label: 'تابع المشاهدة' });
    var v = rows.vodNew, s = rows.seriesNew;
    for (i = 0; f.length < 6 && (i < v.length || i < s.length) && i < 3; i++) {
      if (v[i]) f.push({ kind: 'vod', item: v[i], label: 'جديد في الأفلام' });
      if (s[i]) f.push({ kind: 'series', item: s[i], label: 'جديد في المسلسلات' });
    }
    if (!f.length) {
      var ch = Store.getLastChannel();
      if (ch && Parental.filter('live', [ch]).length) f.push({ kind: 'live', item: ch, label: 'آخر قناة شاهدتها' });
    }
    return f;
  },

  /* ---------------- the big picture ----------------
     a row of slides that the finger can drag (it snaps to the nearest one) and
     that slides on by itself; the picture of each slide loads when it is near */
  slideHtml: function (hero, i) {
    var it = hero.item, rec = hero.rec, meta = [], label = 'شاهد الآن', info = 'التفاصيل';
    if (rec && rec.kind === 'vod') { label = 'استكمال'; if (rec.dur > 0) meta.push('باقي ' + this.left(rec)); }
    else if (rec) { label = rec.done ? 'الحلقة التالية' : 'استكمال'; info = 'الحلقات'; meta.push((rec.season ? 'الموسم ' + rec.season : '') + (rec.num ? ' · الحلقة ' + rec.num : '')); }
    if (!rec && it.year) meta.push(String(it.year));
    if (!rec && it.rating) meta.push('★ ' + it.rating);
    if (hero.kind === 'series' && !rec) info = 'الحلقات';
    var prog = rec && rec.dur > 0 ? '<div class="t-bar"><i style="width:' + Math.min(100, Math.round(rec.pos / rec.dur * 100)) + '%"></i></div>' : '';
    return '<div class="th-slide' + (hero.kind === 'live' ? ' live' : '') + '" data-s="' + i + '"><div class="th-bg"></div><div class="th-shade"></div>' +
      '<div class="th-hero-in">' + (hero.kind === 'live' ? '<div class="th-side logo">' + T.pic(it.icon, it.name, 'logo') + '</div>' :
      '<div class="th-side">' + T.pic(it.icon, it.name, 'poster') + '</div>') + '<div class="th-txt">' +
      '<span class="th-kicker">' + T.esc(hero.label) + '</span>' +
      '<h1>' + T.esc(it.name) + '</h1>' +
      (meta.length ? '<div class="th-meta">' + T.esc(meta.join(' · ')) + '</div>' : '') + prog +
      '<p class="th-plot"></p>' +
      '<div class="th-btns"><button type="button" class="t-btn" data-act="hero" data-k="play" data-i="' + i + '">' + T.ICON.play + label + '</button>' +
      (hero.kind !== 'live' ? '<button type="button" class="t-btn ghost" data-act="hero" data-k="info" data-i="' + i + '">' + T.ICON.info + info + '</button>' : '') +
      '</div></div></div></div>';
  },

  drawHero: function () {
    var self = this, track = U.$('th-track');
    if (!track) return;
    var n = this.feats.length, h = '', dots = '';
    if (!n) {
      h = '<div class="th-slide empty"><div class="th-bg"></div><div class="th-shade"></div><div class="th-hero-in"><div class="th-txt">' +
        (this.latest.vod && this.latest.series ? '<span class="th-kicker">' + T.esc(BRAND.name) + '</span><h1>كل أفلامك وقنواتك في مكان واحد</h1>' : '<div class="t-spin small"></div>') +
        '</div></div></div>';
    }
    for (var i = 0; i < n; i++) h += this.slideHtml(this.feats[i], i);
    for (var d = 0; n > 1 && d < n; d++) dots += '<button type="button" class="th-dot" data-act="dot" data-i="' + d + '" aria-label="' + (d + 1) + '"></button>';
    track.innerHTML = h;
    U.$('th-dots').innerHTML = dots;
    if (this.fi >= n) this.fi = 0;
    /* start on the slide shown before (no animation) */
    track.scrollLeft = this.slideX(this.fi);
    this.markSlide(this.fi);
    if (!track.__bound) {
      track.__bound = true;
      var t = null;
      track.addEventListener('scroll', function () {
        clearTimeout(t);
        t = setTimeout(function () { self.markSlide(self.slideAt()); }, 90);
      }, { passive: true });
      /* the finger is on the picture: no turning by itself for a while */
      var hold = function () { self.touchedAt = U.now(); };
      track.addEventListener('touchstart', hold, { passive: true });
      track.addEventListener('touchmove', hold, { passive: true });
      track.addEventListener('mousedown', hold);
    }
  },

  /* the scroll position of slide i (the row runs right-to-left: positions are negative) */
  slideX: function (i) {
    var track = U.$('th-track'), w = track ? track.clientWidth : 0;
    var rtl = track && window.getComputedStyle(track).direction === 'rtl';
    return (rtl ? -1 : 1) * i * w;
  },
  slideAt: function () {
    var track = U.$('th-track');
    if (!track || !track.clientWidth) return 0;
    return Math.max(0, Math.min(this.feats.length - 1, Math.round(Math.abs(track.scrollLeft) / track.clientWidth)));
  },
  goSlide: function (i, instant) {
    var track = U.$('th-track');
    if (!track || !this.feats.length) return;
    i = (i + this.feats.length) % this.feats.length;
    var x = this.slideX(i);
    if (instant || !track.scrollTo) track.scrollLeft = x;
    else track.scrollTo({ left: x, behavior: 'smooth' });
    this.markSlide(i);
  },
  /* the slide in view: its dot, its words fading in, its picture (and the next one's) loading */
  markSlide: function (i) {
    this.fi = i;
    var sl = document.querySelectorAll('#th-track .th-slide'), dots = document.querySelectorAll('#th-dots .th-dot');
    for (var k = 0; k < sl.length; k++) U.toggleClass(sl[k], 'on', k === i);
    for (var j = 0; j < dots.length; j++) U.toggleClass(dots[j], 'on', j === i);
    this.loadBackdrop(i);
    if (this.feats.length > 1) this.loadBackdrop((i + 1) % this.feats.length);
  },

  startTurn: function () {
    var self = this;
    clearInterval(this.turn);
    if (this.feats.length < 2) return;
    this.turn = setInterval(function () {
      if (App.current() !== 't_home' || UI.modal() || T.sheetOpen()) return;
      if (self.touchedAt && U.now() - self.touchedAt < 8000) return;
      self.goSlide(self.slideAt() + 1);
    }, 7000);
  },

  left: function (rec) {
    var m = Math.max(1, Math.round((rec.dur - rec.pos) / 60000));
    return m >= 60 ? Math.floor(m / 60) + ' س ' + (m % 60) + ' د' : m + ' د';
  },

  /* the film's / series' wide picture and story when the server has them (once per slide) */
  loadBackdrop: function (i) {
    var hero = this.feats[i], slide = document.querySelector('#th-track .th-slide[data-s="' + i + '"]');
    if (!hero || !slide || slide.__bg) return;
    slide.__bg = true;
    var bg = slide.querySelector('.th-bg'), it = hero.item;
    U.setBg(bg, it.icon);
    if (hero.kind === 'live') return;
    var done = function (info) {
      if (!slide.parentNode) return;
      var b = info && info.backdrop_path;
      if (b && typeof b !== 'string') b = b[0];
      if (b) {
        /* show the wide picture once it has arrived, so it does not appear in pieces */
        var img = new Image();
        img.onload = function () { U.setBg(bg, b); U.addClass(slide, 'wide'); };
        img.src = U.bgUrl(b);
      }
      var plot = info && (info.plot || info.description), p = slide.querySelector('.th-plot');
      if (plot && p) p.innerHTML = T.esc(plot);
    };
    if (hero.kind === 'vod') Xtream.getVodInfo(it.id, function (e, d) { if (!e) done(d && d.info); });
    else Xtream.getSeriesInfo(it.id, function (e, d) { if (!e) done(d && d.info); });
  },

  /* ---------------- rows ---------------- */
  row: function (k, title, items, look, more, loading) {
    var h = '<section class="th-sec"><div class="th-sec-head"><h2>' + T.esc(title) + '</h2>' +
      (more && items.length ? '<button type="button" class="t-link" data-act="more" data-k="' + more + '">عرض الكل</button>' : '') + '</div>' +
      '<div class="th-row r-' + look + '">';
    if (loading) {
      for (var p = 0; p < 8; p++) h += '<div class="th-card ghost"><span class="t-pic ' + look + '"></span><b>&nbsp;</b></div>';
    } else if (!items.length) {
      h += '<p class="th-none">لا يوجد شيء هنا بعد.</p>';
    }
    for (var i = 0; i < items.length && i < 30; i++) {
      var rec = k === 'cont' ? items[i] : null, it = rec ? rec.item : items[i];
      var sub = '';
      if (rec && rec.kind === 'series') sub = (rec.season ? 'م' + rec.season + ' ' : '') + (rec.num ? 'ح' + rec.num : '');
      else if (rec && rec.dur > 0) sub = 'باقي ' + this.left(rec);
      else if (it.year) sub = String(it.year) + (it.rating ? ' · ★ ' + it.rating : '');
      h += '<button type="button" class="th-card" data-act="item" data-k="' + k + '" data-i="' + i + '">' +
        T.pic(it.icon, it.name, look) + (k === 'top' ? '<span class="tb-rank">' + (i + 1) + '</span>' + (Sagas.isOscar(it) ? '<span class="tb-osc">' + T.ICON.trophy + 'أوسكار</span>' : '') : '') +
        (rec && rec.dur > 0 ? '<div class="t-bar"><i style="width:' + Math.min(100, Math.round(rec.pos / rec.dur * 100)) + '%"></i></div>' : '') +
        '<b>' + T.esc(it.name) + '</b>' + (sub ? '<small>' + T.esc(sub) + '</small>' : '') + '</button>';
    }
    return h + '</div></section>';
  },

  itemOf: function (k, i) {
    var r = this.rowsData[k];
    if (k === 'sagas') return null;
    if (!r || !r[i]) return null;
    return k === 'cont' ? r[i].item : r[i];
  },

  open: function (k, i) {
    var r = this.rowsData[k];
    if (!r || !r[i]) return;
    if (k === 'cont') {
      var rec = r[i];
      if (rec.kind === 'vod') App.go('player', { kind: 'movie', item: rec.item, startAt: rec.pos || 0 });
      else App.go('series', { item: rec.item, autoplay: true });
    } else if (k === 'live') {
      App.go('player', { kind: 'live', list: r, index: i, catName: 'المفضلة' });
    } else if (k === 'sagas') {
      App.go('saga', { saga: r[i] });
    } else if (k === 'vod' || k === 'vodNew' || k === 'top') App.go('movie', { item: r[i] });
    else App.go('series', { item: r[i] });
  },

  heroAction: function (k, i) {
    var hero = this.feats[i === undefined || isNaN(i) ? this.fi : i];
    if (!hero) return;
    var it = hero.item, rec = hero.rec;
    if (hero.kind === 'live') {
      var favs = Parental.filter('live', Store.getFavs('live'));
      for (var i = 0; i < favs.length; i++) {
        if (String(favs[i].id) === String(it.id)) { App.go('player', { kind: 'live', list: favs, index: i, catName: 'المفضلة' }); return; }
      }
      App.go('player', { kind: 'live', list: [it], index: 0, catName: '' });
    } else if (hero.kind === 'vod') {
      if (k === 'info' || !rec) { if (k === 'info') App.go('movie', { item: it }); else App.go('player', { kind: 'movie', item: it, startAt: 0 }); }
      else App.go('player', { kind: 'movie', item: it, startAt: rec.pos || 0 });
    } else {
      App.go('series', { item: it, autoplay: k !== 'info' && !!rec });
    }
  },

  onKey: function (k) {
    if (k !== 'back') return;
    if (T.closeSheet()) return;
    /* leaving the first screen: the app goes to the background, like any phone app */
    try { tizen.application.getCurrentApplication().hide(); } catch (e) { App.exitConfirm(); }
  }
};

/* ==========================================================================
   Live TV, films, series and favourites on a phone / tablet.
   Sections as chips at the top (all of them in a sheet), or as a column on
   the side of a wide screen; channels as a list, films and series as posters.
   ========================================================================== */
(function () {
  var TITLE = { live: 'البث المباشر', vod: 'الأفلام', series: 'المسلسلات', fav: 'المفضلة' };
  var ALL = { live: 'كل القنوات', vod: 'كل الأفلام', series: 'كل المسلسلات' };
  var EMPTY = {
    __fav: 'لا يوجد شيء في المفضلة بعد. اضغط مطوّلاً على أي قناة أو فيلم أو مسلسل لإضافته.',
    __cont: 'لا يوجد شيء لمتابعته حتى الآن.',
    __hist: 'القنوات التي تشاهدها تظهر هنا.',
    __top: 'لم نجد في قائمتك شيئاً من قوائم الأفضل في التاريخ.',
    __saga: 'لم نجد في قائمتك سلسلة أفلام فيها 3 أجزاء أو أكثر.',
    other: 'لا يوجد محتوى في هذا القسم.'
  };
  var FAVTYPES = [{ id: 'live', name: 'القنوات' }, { id: 'vod', name: 'الأفلام' }, { id: 'series', name: 'المسلسلات' }];
  var lastCat = {};       /* the section each tab was on, for coming back */
  var NEW_MAX = 60;       /* «المضاف حديثاً»: the newest additions to the server */

  var S = Screens.t_browse = { type: 'live', cats: [], cur: null, items: [], req: 0, favType: 'live' };

  S.show = function (params) {
    var self = this;
    this.type = params.type || 'live';
    this.startId = params.start || null;
    this.items = [];
    this.cur = null;
    this.cats = [];
    var el = this.el;
    var isFav = this.type === 'fav';
    el.className = 'screen t-screen with-tabs tb-' + this.type;
    var acts = ['search', 'settings'];
    if (this.type === 'vod' || this.type === 'series') acts.unshift(this.sortBtn());
    el.innerHTML = T.top({ title: TITLE[this.type], sub: '', subId: 'tb-sub', actions: acts }) +
      '<div class="tb-cats" id="tb-chips"></div>' +
      '<div class="tb-body"><aside class="tb-sidebox"><div class="t-field tb-find">' + T.ICON.search +
      '<input id="tb-find" type="search" autocomplete="off" placeholder="ابحث في الأقسام"></div><div class="tb-side t-scroll" id="tb-side"></div></aside>' +
      '<div class="tb-main"><div class="tb-list" id="tb-list"></div><div class="t-state" id="tb-state"></div></div>' +
      '<aside class="tb-prev" id="tb-prev"></aside></div>' +
      T.tabs(this.type);
    this.list = new T.TList(U.$('tb-list'), this.listOpts());
    this.catQ = '';
    this.counts = {};
    this.stopPreview();
    var find = U.$('tb-find');
    find.addEventListener('input', function () { self.catQ = find.value; self.drawCats(self.cur ? self.cur.id : null); });
    this.layoutPreview();
    T.bind(el, {
      full: function () { self.previewFull(); },
      search: function () { App.go('search', { type: self.kindOf() }); },
      sort: function () { self.flipSort(); },
      cat: function (t) { self.pickCat(t.getAttribute('data-id')); },
      allcats: function () { self.catSheet(); },
      favtype: function (t) { self.favType = t.getAttribute('data-id'); lastCat.favType = self.favType; self.showFavs(); self.layoutPreview(); },
      retry: function () { if (self.cats.length) self.pickCat(self.cur ? self.cur.id : self.cats[0].id); else self.show({ type: self.type }); }
    });
    if (!el.__held) {
      el.__held = true;
      T.holdable(el, '[data-act="cat"]', function (t) {
        var c = self.catById(t.getAttribute('data-id'));
        if (c && self.isReal(c)) self.catMenu(c);
      });
    }
    if (isFav) {
      this.favType = params.favType || lastCat.favType || 'live';
      lastCat.favType = this.favType;
      this.showFavs();
      this.layoutPreview();
      return;
    }
    this.loadCats();
  };

  S.resume = function (back) {
    var self = this;
    this.layoutPreview();
    /* back from the full-screen channel: it goes on playing in the preview */
    var pl = this.pvBack;
    this.pvBack = null;
    if (this.wide() && pl && back && back.index !== undefined && pl[back.index]) setTimeout(function () { self.preview(pl, back.index); }, 280);
    if (this.type === 'fav') { this.showFavs(true); return; }
    /* favourites / recent channels / continue watching may have changed meanwhile */
    if (this.counts && this.counts.__all !== undefined) { this.specialCounts(); this.drawCats(this.cur ? this.cur.id : null); }
    var id = this.cur && this.cur.id;
    if (id === '__fav' || id === '__cont' || id === '__hist') this.loadItems(this.cur, true);
    else this.list.refresh();
  };

  S.hide = function () { T.closeSheet(); this.stopPreview(); };

  /* ---------------- list look ---------------- */
  S.listOpts = function () {
    var self = this;
    return {
      cols: function (w) {
        if (self.kindOf() === 'live') return 1;          /* channels: one list, like other IPTV players */
        return Math.max(3, Math.floor(w / (Device.phone() ? 118 : 158)));
      },
      rowH: function (w, cols) {
        if (self.kindOf() === 'live') return Device.phone() ? 64 : 70;
        var cw = (w - 20) / cols - 10;          /* poster width inside its cell */
        return Math.round(cw * 1.5 + 56);
      },
      padBottom: 24,
      render: function (it, i) { return self.cell(it, i); },
      onTap: function (it, i) {
        if (it.type === 'saga') { App.go('saga', { saga: it.saga }); return; }
        /* a wide tablet: the first tap shows the channel in the preview, the second fills the screen */
        if (self.wide()) { if (self.pv && String(self.pv.id) === String(it.id)) self.previewFull(); else self.preview(self.items, i); return; }
        self.open(it, i);
      },
      onHold: function (it, i) {
        if (it.type === 'saga') return;
        T.favToast(Store.toggleFav(it));
        if (self.type === 'fav' || (self.cur && self.cur.id === '__fav')) self.resume();
        else self.list.update(i);
      }
    };
  };

  S.kindOf = function () { return this.type === 'fav' ? this.favType : this.type; };

  /* a film series shows as a little pile of its posters */
  S.sagaCells = function (list) {
    var out = [];
    for (var i = 0; i < (list || []).length; i++) out.push({ type: 'saga', id: 'saga:' + list[i].id, name: list[i].name, saga: list[i] });
    return out;
  };
  S.cell = function (it, i) {
    if (it.type === 'saga') return '<div class="tb-po tb-sg">' + T.sagaPile(it.saga) + '<b>' + T.esc(it.name) + '</b><small>' +
      T.esc(Sagas.partsText(it.saga.count) + (it.saga.from ? ' · ' + Sagas.yearsText(it.saga) : '')) + '</small></div>';
    var kind = this.kindOf(), fav = Store.isFav(kind, it.id) ? '<span class="tb-star">' + T.ICON.fav + '</span>' : '';
    if (kind === 'live') {
      return '<div class="tb-ch' + (this.pv && String(this.pv.id) === String(it.id) ? ' sel' : '') + '"><span class="tb-num">' + T.esc(String(it.num || (i + 1))) + '</span>' + T.pic(it.icon, it.name, 'logo') +
        '<div class="tb-ch-t"><b>' + T.esc(it.name) + '</b></div>' + fav + '</div>';
    }
    var meta = [];
    if (it.year) meta.push(it.year);
    if (it.rating) meta.push('★ ' + it.rating);
    /* the best rated list: its place on the poster */
    var rank = this.cur && this.cur.id === '__top' ? '<span class="tb-rank">' + (i + 1) + '</span>' + (Sagas.isOscar(it) ? '<span class="tb-osc">' + T.ICON.trophy + 'أوسكار</span>' : '') : '';
    return '<div class="tb-po">' + T.pic(it.icon, it.name, 'poster') + fav + rank +
      '<b>' + T.esc(it.name) + '</b>' + (meta.length ? '<small>' + T.esc(meta.join(' · ')) + '</small>' : '') + '</div>';
  };

  /* ---------------- sections ---------------- */
  S.specials = function () {
    var s = [{ id: '__all', name: ALL[this.type] }, { id: '__fav', name: 'المفضلة' }];
    if (this.type === 'live') s.push({ id: '__hist', name: 'آخر القنوات' });
    else s.push({ id: '__cont', name: 'تابع المشاهدة' }, { id: '__new', name: 'المضاف حديثاً' }, { id: '__top', name: 'الأعلى تقييماً' });
    if (this.type === 'vod') s.push({ id: '__saga', name: 'سلاسل الأفلام' });
    return s;
  };
  S.isReal = function (c) { return c && String(c.id).indexOf('__') !== 0; };
  S.catById = function (id) {
    for (var i = 0; i < this.cats.length; i++) if (String(this.cats[i].id) === String(id)) return this.cats[i];
    return null;
  };

  S.loadCats = function () {
    var self = this, my = ++this.req;
    this.state('loading');
    Xtream.getCategories(this.type, function (err, cats) {
      if (my !== self.req) return;
      if (err) { self.state('error', Xtream.errorText(err), true); return; }
      self.rawCats = cats;
      self.cats = self.specials().concat(Parental.arrange(self.type, cats));
      var want = self.startId || lastCat[self.type];
      self.startId = null;
      var c = want && self.catById(want);
      if (!c || (c.locked && !Parental.isUnlocked())) {
        if (self.type !== 'live' && Store.continueList(self.type).length) c = self.catById('__cont');
        else if (Store.getFavs(self.type).length) c = self.catById('__fav');
        else c = self.cats[self.specials().length] || self.cats[0];
      }
      self.drawCats(c.id);
      self.loadItems(c);
      self.loadCounts();
    });
  };

  /* how many channels / films / series each section has (from the full list, once) */
  S.loadCounts = function () {
    var self = this, type = this.type;
    Xtream.getStreams(type, null, function (err, all) {
      if (err || !all || self.type !== type) return;
      var n = {}, vis = Parental.filter(type, all);
      for (var i = 0; i < all.length; i++) n[all[i].cat] = (n[all[i].cat] || 0) + 1;
      n.__all = vis.length;
      self.counts = n;
      self.specialCounts();
      self.drawCats(self.cur ? self.cur.id : null);
      if (type === 'live') return;
      /* the best rated and the film series: their numbers once they are counted */
      Sagas.top(type, function (e, l) {
        if (self.type !== type || self.counts !== n) return;
        n.__top = (l || []).length;
        if (type !== 'vod') { self.drawCats(self.cur ? self.cur.id : null); return; }
        Sagas.get(function (e2, sg) {
          if (self.type !== type || self.counts !== n) return;
          n.__saga = (sg || []).length;
          self.drawCats(self.cur ? self.cur.id : null);
        });
      });
    });
  };
  S.specialCounts = function () {
    var t = this.type, n = this.counts;
    n.__fav = Parental.filter(t, Store.getFavs(t)).length;
    if (t === 'live') n.__hist = Parental.filter('live', Store.liveHistory()).length;
    else { n.__cont = Parental.filter(t, Store.continueList(t)).length; n.__new = Math.min(NEW_MAX, n.__all || 0); }
  };

  S.drawCats = function (curId) {
    var h = '', side = '', n = 0, q = Xtream.simplify(String(this.catQ || '').replace(/^\s+|\s+$/g, ''));
    for (var i = 0; i < this.cats.length; i++) {
      var c = this.cats[i], on = String(c.id) === String(curId) ? ' on' : '';
      var lock = c.locked ? '<i class="tb-lock">' + T.ICON.lock + '</i>' : '';
      var cnt = this.counts && this.counts[c.id] !== undefined && !c.locked ? '<em>' + this.counts[c.id] + '</em>' : '';
      if (!q || on || Xtream.simplify(c.name).indexOf(q) !== -1) {
        side += '<button type="button" class="tb-srow' + on + '" data-act="cat" data-id="' + T.esc(String(c.id)) + '">' + lock + '<span>' + T.esc(c.name) + '</span>' + cnt + '</button>';
      }
      /* chips: the special ones, the current one and the first few sections; all of them are in the sheet */
      if (n < 14 || on) { h += '<button type="button" class="t-chip' + on + '" data-act="cat" data-id="' + T.esc(String(c.id)) + '">' + lock + T.esc(c.name) + '</button>'; n++; }
    }
    h = '<button type="button" class="t-chip all" data-act="allcats">' + T.ICON.cats + 'كل الأقسام</button>' + h;
    U.$('tb-chips').innerHTML = '<div class="t-chips">' + h + '</div>';
    U.$('tb-side').innerHTML = side;
    var on1 = U.$('tb-chips').querySelector('.t-chip.on');
    if (on1 && on1.scrollIntoView) on1.scrollIntoView({ block: 'nearest', inline: 'center' });
    var on2 = U.$('tb-side').querySelector('.tb-srow.on');
    if (on2 && !q) U.$('tb-side').scrollTop = Math.max(0, on2.offsetTop - 160);
  };

  S.catSheet = function () {
    var self = this, items = [];
    for (var i = 0; i < this.cats.length; i++) {
      var c = this.cats[i];
      items.push({ label: c.name, value: String(c.id), selected: this.cur && String(this.cur.id) === String(c.id), locked: c.locked, cat: c,
        sub: this.counts && this.counts[c.id] !== undefined && !c.locked ? String(this.counts[c.id]) : '' });
    }
    T.sheet({
      title: 'الأقسام', items: items, search: items.length > 12,
