      onHold: function (it) { if (self.isReal(it.cat)) { T.closeSheet(); self.catMenu(it.cat); } }
    });
  };

  S.pickCat = function (id) {
    var self = this, c = this.catById(id);
    if (!c) return;
    if (c.locked && !Parental.isUnlocked()) {
      Parental.ask('هذا القسم محمي برمز حماية الأطفال', function (ok) {
        if (!ok) return;
        self.cats = self.specials().concat(Parental.arrange(self.type, self.rawCats || []));
        self.drawCats(id);
        self.loadItems(self.catById(id));
      });
      return;
    }
    this.drawCats(id);
    this.loadItems(c);
  };

  S.loadItems = function (c, keep) {
    var self = this, type = this.type;
    this.cur = c;
    lastCat[type] = String(c.id);
    var sub = U.$('tb-sub');
    if (sub) sub.innerHTML = T.esc(c.name);
    if (c.id === '__fav') return this.showItems(Parental.filter(type, Store.getFavs(type)), EMPTY.__fav, keep);
    if (c.id === '__cont') return this.showItems(Parental.filter(type, Store.continueList(type)), EMPTY.__cont, keep);
    if (c.id === '__hist') return this.showItems(Parental.filter('live', Store.liveHistory()), EMPTY.__hist, keep);
    if (c.id === '__new') {
      var myN = ++this.req;
      this.list.set([]);
      this.state('loading');
      Xtream.getStreams(type, null, function (err, all) {
        if (myN !== self.req) return;
        if (err) { self.state('error', Xtream.errorText(err), true); return; }
        var l = Parental.filter(type, all).slice();
        l.sort(function (a, b) { return (b.added || 0) - (a.added || 0); });
        self.showItems(l.slice(0, NEW_MAX), EMPTY.other);
      });
      return;
    }
    if (c.id === '__top' || c.id === '__saga') {
      var myS = ++this.req;
      this.list.set([]);
      this.state('loading');
      var got = function (err, l) {
        if (myS !== self.req) return;
        if (err) { self.state('error', Xtream.errorText(err), true); return; }
        self.showItems(c.id === '__saga' ? self.sagaCells(l) : l, EMPTY[c.id], keep);
      };
      if (c.id === '__top') Sagas.top(type, got); else Sagas.get(got);
      return;
    }
    var my = ++this.req;
    this.list.set([]);
    this.state('loading');
    Xtream.getStreams(type, c.id === '__all' ? null : c.id, function (err, items) {
      if (my !== self.req) return;
      if (err) { self.state('error', Xtream.errorText(err), true); return; }
      if (c.id === '__all') items = Parental.filter(type, items);
      if (type !== 'live') items = self.order(items);
      self.showItems(items, EMPTY.other);
    });
  };

  S.showItems = function (items, empty, keep) {
    this.items = items || [];
    U.toggleClass(U.$('tb-list'), 'is-live', this.kindOf() === 'live');
    this.list.set(this.items, keep);
    this.state(this.items.length ? '' : 'empty', empty);
    var sub = U.$('tb-sub');
    if (sub && this.cur) sub.innerHTML = T.esc(this.cur.name) + (this.items.length ? ' · ' + this.items.length : '');
  };

  S.state = function (k, text, retry) { T.state(U.$('tb-state'), k === 'empty' ? 'msg' : k === 'error' ? 'msg' : k, text, retry); };

  /* ---------------- channel preview (wide tablets / car screens) ----------------
     channels on the left, the chosen one playing on the right with what is on now and next */
  S.wide = function () {
    return this.kindOf() === 'live' && !!(Player.setRect) && Device.touch() && !Device.phone() && Device.landscape() && window.innerWidth >= 1000;
  };
  S.layoutPreview = function () {
    var on = this.wide();
    U.toggleClass(this.el, 'has-prev', on);
    if (!on) { this.stopPreview(); return; }
    if (!this.pv) this.drawPane(null);
    else this.placeVideo();
  };
  S.drawPane = function (it, i) {
    var box = U.$('tb-prev');
    if (!box) return;
    if (!it) {
      box.innerHTML = '<div class="tb-pv" id="tb-pv"><div class="tb-pv-msg">' + T.ICON.live + '<span>اختر قناة لعرضها هنا</span></div></div>';
      return;
    }
    box.innerHTML = '<div class="tb-pv" id="tb-pv"><div class="tb-pv-msg" id="tb-pv-msg"><div class="t-spin"></div></div></div>' +
      '<div class="tb-pv-info"><span class="tb-num">' + T.esc(String(it.num || (i + 1))) + '</span>' + T.pic(it.icon, it.name, 'logo') +
      '<b>' + T.esc(it.name) + '</b><button type="button" class="t-btn" data-act="full">' + T.ICON.expand + 'ملء الشاشة</button></div>' +
      '<div class="tb-pv-epg" id="tb-pv-epg"></div>';
  };
  S.placeVideo = function () {
    var b = U.$('tb-pv');
    if (!b || !Player.setRect) return;
    var r = b.getBoundingClientRect();
    Player.setRect({ x: r.left, y: r.top, w: r.width, h: r.height });
  };
  /* list, i: the section the channel was picked from (full screen then moves through that section) */
  S.preview = function (list, i) {
    var self = this, it = list[i];
    if (!it || !this.wide()) return;
    this.pv = it; this.pvList = list; this.pvI = i;
    this.markSel();
    this.drawPane(it, i);
    this.placeVideo();
    var fmt = Store.getSettings().liveFormat || 'ts', my = this.pvTok = (this.pvTok || 0) + 1;
    Player.play(Xtream.liveUrl(it, fmt), {
      live: true, preview: true,
      on: function (e, d) {
        if (my !== self.pvTok) return;
        var m = U.$('tb-pv-msg');
        if (!m) return;
        if (e === 'buffer') m.innerHTML = d ? '<div class="t-spin"></div>' : '';
        else if (e === 'state' && d === 'playing') m.innerHTML = '';
        else if (e === 'error') m.innerHTML = '<span>لم تظهر القناة هنا — اضغط «ملء الشاشة» لتشغيلها</span>';
      }
    });
    Xtream.getShortEpg(it.id, function (err, l) {
      if (my !== self.pvTok) return;
      var box = U.$('tb-pv-epg');
      if (!box) return;
      if (err || !l || !l.length) { box.innerHTML = '<p class="muted">لا يوجد دليل برامج لهذه القناة.</p>'; return; }
      var h = '', now = U.now();
      for (var k = 0; k < l.length && k < 4; k++) {
        var p = l[k], cur = p.start <= now && p.end > now;
        var pct = cur && p.end > p.start ? Math.round((now - p.start) / (p.end - p.start) * 100) : 0;
        h += '<div class="tb-ep' + (cur ? ' now' : '') + '"><span class="tb-ep-t" dir="ltr">' + U.fmtClock(new Date(p.start)) + '</span>' +
          '<div><b>' + T.esc(p.title) + '</b>' + (cur ? '<div class="t-bar"><i style="width:' + pct + '%"></i></div>' : '') + '</div></div>';
      }
      box.innerHTML = h;
    });
  };
  /* the channel in the preview, full screen */
  S.previewFull = function () {
    if (!this.pv) return;
    var list = this.pvList, i = this.pvI;
    this.stopPreview(true);
    this.pvBack = list;
    App.go('player', { kind: 'live', list: list, index: i, catName: this.cur ? this.cur.name : '' });
  };
  S.stopPreview = function (keepPane) {
    var was = !!this.pv;
    this.pv = null;
    this.pvTok = (this.pvTok || 0) + 1;
    if (was) Player.stop();
    if (Player.setRect) Player.setRect(null);
    if (was && !keepPane && this.list) { this.markSel(); this.drawPane(null); }
  };
  /* the row of the channel in the preview stands out */
  S.markSel = function () {
    var l = U.$('tb-list');
    if (!l) return;
    var cells = l.querySelectorAll('.tl-cell');
    for (var k = 0; k < cells.length; k++) {
      var it = this.items[parseInt(cells[k].getAttribute('data-i'), 10)], ch = cells[k].firstChild;
      if (ch && ch.className && ch.className.indexOf('tb-ch') === 0) U.toggleClass(ch, 'sel', !!(this.pv && it && String(it.id) === String(this.pv.id)));
    }
  };

  /* a tap on the picture itself: full screen */
  (function () {
    var v = U.$('html5-player');
    if (v) v.addEventListener('click', function () { if (App.current() === 't_browse' && S.pv) S.previewFull(); });
    window.addEventListener('resize', function () { if (App.current() === 't_browse') setTimeout(function () { S.layoutPreview(); }, 60); });
  })();

  /* ---------------- newest / oldest first (films and series) ----------------
     inside every section the newest are on top; the arrow button turns it round */
  function oldestFirst(list) {
    return list.slice().sort(function (a, b) {
      return ((a.year || 9999) - (b.year || 9999)) || ((a.added || 0) - (b.added || 0));
    });
  }
  S.sortDir = function () { var st = Store.getSettings(); return st.sort === 'server' ? 'server' : (st.sortDir === 'old' ? 'old' : 'new'); };
  S.order = function (items) {
    var d = this.sortDir();
    if (d === 'server') return items;
    return d === 'old' ? oldestFirst(items) : Xtream.newestFirst(items);
  };
  S.sortBtn = function () {
    var old = this.sortDir() === 'old';
    return { act: 'sort', id: 'tb-sort', icon: old ? T.ICON.sortOld : T.ICON.sortNew, label: old ? 'الأقدم أولاً' : 'الأحدث أولاً' };
  };
  S.flipSort = function () {
    var next = this.sortDir() === 'new' ? 'old' : 'new';
    Store.setSetting('sort', 'new');
    Store.setSetting('sortDir', next);
    var b = U.$('tb-sort');
    if (b) { b.innerHTML = next === 'old' ? T.ICON.sortOld : T.ICON.sortNew; b.setAttribute('aria-label', next === 'old' ? 'الأقدم أولاً' : 'الأحدث أولاً'); }
    UI.toast(next === 'old' ? 'الأقدم أولاً' : 'الأحدث أولاً', 1400);
    /* the list on screen turns round too (special lists keep their own order) */
    var id = this.cur && String(this.cur.id);
    if (this.items.length && (this.isReal(this.cur) || id === '__all')) {
      this.items = this.order(this.items);
      this.list.set(this.items);
    }
  };

  /* ---------------- favourites tab ---------------- */
  S.showFavs = function (keep) {
    var h = '<div class="t-seg">';
    for (var i = 0; i < FAVTYPES.length; i++) {
      h += '<button type="button" class="' + (FAVTYPES[i].id === this.favType ? 'on' : '') + '" data-act="favtype" data-id="' + FAVTYPES[i].id + '">' + FAVTYPES[i].name + '</button>';
    }
    U.$('tb-chips').innerHTML = h + '</div>';
    U.$('tb-side').innerHTML = '';
    this.cur = { id: '__fav', name: 'المفضلة' };
    var items = Parental.filter(this.favType, Store.getFavs(this.favType));
    this.items = items;
    U.toggleClass(U.$('tb-list'), 'is-live', this.favType === 'live');
    this.list.set(items, keep);
    this.state(items.length ? '' : 'empty', EMPTY.__fav);
    var sub = U.$('tb-sub');
    if (sub) sub.innerHTML = items.length ? String(items.length) : '';
  };

  /* ---------------- opening ---------------- */
  S.open = function (it, i, fromPreview) {
    var kind = this.kindOf();
    if (this.pv) this.stopPreview(true);
    if (kind === 'live') App.go('player', { kind: 'live', list: this.items, index: i, catName: this.cur ? this.cur.name : '' });
    else if (kind === 'vod') App.go('movie', { item: it });
    else App.go('series', { item: it });
  };

  /* holding a section: lock it, hide it, or put it first */
  S.catMenu = function (c) {
    var self = this, type = this.type;
    UI.menu({
      title: c.name,
      items: [
        { label: 'نقل لأول القائمة', value: 'top' },
        { label: c.locked ? 'إلغاء قفل القسم' : 'قفل القسم برمز', sub: c.locked ? '' : 'لا يُفتح إلا برمز حماية الأطفال', value: 'lock' },
        { label: 'إخفاء القسم', sub: 'يمكنك إظهاره من الإعدادات', value: 'hide' }
      ],
      onSelect: function (v) {
        if (!v) return;
        var go = function () {
          if (v === 'top') {
            var ids = [String(c.id)];
            for (var i = 0; i < self.cats.length; i++) if (self.isReal(self.cats[i]) && String(self.cats[i].id) !== String(c.id)) ids.push(String(self.cats[i].id));
            Parental.setOrder(type, ids);
            UI.toast('أصبح «' + c.name + '» أول قسم');
          } else if (v === 'lock') {
            Parental.setLocked(type, c, !c.locked);
            UI.toast(c.locked ? 'تم إلغاء قفل «' + c.name + '»' : 'تم قفل «' + c.name + '» ويُفتح بالرمز');
          } else if (v === 'hide') {
            Parental.setHidden(type, c, true);
            UI.toast('تم إخفاء «' + c.name + '»، ويمكنك إظهاره من الإعدادات', 4000);
          }
          var keepId = self.cur ? self.cur.id : null;
          self.cats = self.specials().concat(Parental.arrange(type, self.rawCats || []));
          var still = keepId && self.catById(keepId);
          if (!still || (still.locked && !Parental.isUnlocked())) still = self.cats[0];
          self.drawCats(still.id);
          if (!self.cur || String(still.id) !== String(self.cur.id)) self.loadItems(still);
        };
        if (v === 'lock' && !c.locked && !Parental.has()) { Parental.create(function (ok) { if (ok) go(); }); return; }
        Parental.ask('لتعديل الأقسام', function (ok) { if (ok) go(); });
      }
    });
  };

  S.onKey = function (k) {
    if (k !== 'back') return;
    if (T.closeSheet()) return;
    T.goTab('home');
  };
})();

/* ==========================================================================
   A film's or a series' page on a phone / tablet: the wide picture, poster,
