  }
  function frame(el, it, kind) {
    el.className = 'screen t-screen td td-' + kind;
    el.innerHTML =
      '<div class="t-scroll td-scroll">' +
      '<div class="td-hero"><div class="td-bg" id="td-bg-' + kind + '"></div><div class="td-shade"></div></div>' +
      '<div class="td-top"><button type="button" class="t-ibtn glass t-back" data-act="back" aria-label="رجوع">' + T.ICON.back + '</button>' +
      '<div class="t-grow"></div><button type="button" class="t-ibtn glass" data-act="fav" id="td-fav-' + kind + '" aria-label="المفضلة"></button></div>' +
      '<div class="td-main">' +
      '<div class="td-poster">' + T.pic(it.icon, it.name, 'poster') + '</div>' +
      '<div class="td-info"><h1>' + T.esc(it.name) + '</h1><div class="td-meta" id="td-meta-' + kind + '"></div>' +
      '<div class="td-btns" id="td-btns-' + kind + '"></div>' +
      '<p class="td-plot" id="td-plot-' + kind + '"><span class="muted">جاري تحميل التفاصيل...</span></p>' +
      '<div class="td-credits" id="td-cr-' + kind + '"></div></div>' +
      '</div>' +
      (kind === 'series' ? '<div class="td-seasons" id="td-seasons"></div><div class="td-eps" id="td-eps"></div>' : '<div id="td-saga"></div>') +
      '</div>';
    U.setBg(U.$('td-bg-' + kind), it.icon);
  }
  function favBtn(kind, it) {
    var b = U.$('td-fav-' + kind);
    if (!b) return;
    var on = Store.isFav(kind === 'movie' ? 'vod' : 'series', it.id);
    b.innerHTML = on ? T.ICON.fav : T.ICON.favLine;
    U.toggleClass(b, 'on', on);
  }

  /* ---------------- film ---------------- */
  Screens.t_movie = {
    show: function (params) {
      var self = this, it = this.item = params.item;
      frame(this.el, it, 'movie');
      favBtn('movie', it);
      this.buttons();
      T.bind(this.el, {
        fav: function () { T.favToast(Store.toggleFav(self.item)); favBtn('movie', self.item); },
        resume: function () { var h = Store.getHist('m:' + self.item.id); App.go('player', { kind: 'movie', item: self.item, startAt: h ? h.pos : 0 }); },
        start: function () { App.go('player', { kind: 'movie', item: self.item, startAt: 0 }); },
        saga: function () { if (self.saga) App.go('saga', { saga: self.saga }); },
        sp: function (t) {
          var i = parseInt(t.getAttribute('data-i'), 10), p = self.saga && self.saga.parts[i];
          if (p && String(p.id) !== String(self.item.id)) App.go('movie', { item: p }, { replace: true });
        }
      });
      var my = this.req = (this.req || 0) + 1;
      this.saga = null;
      this.sagaRow();
      Xtream.getVodInfo(it.id, function (err, data) {
        if (my !== self.req) return;
        if (err) { U.$('td-plot-movie').innerHTML = '<span class="muted">' + T.esc(Xtream.errorText(err)) + '</span>'; return; }
        var info = (data && data.info) || {}, md = (data && data.movie_data) || {};
        if (md.container_extension) it.ext = md.container_extension;
        U.setBg(U.$('td-bg-movie'), backdropOf(info, it));
        var year = String(info.releasedate || info.release_date || '').substr(0, 4);
        var r = parseFloat(info.rating) || it.rating;
        U.$('td-meta-movie').innerHTML = chips([year && year !== '0000' ? year : '', info.duration ? String(info.duration).replace(/^00:/, '') : '',
          r ? '★ ' + (Math.round(r * 10) / 10) : '', info.genre || '', info.country || '']);
        U.$('td-plot-movie').innerHTML = T.esc(info.plot || info.description || 'لا يوجد وصف لهذا الفيلم.');
        var cr = '';
        if (info.director) cr += '<div><span>إخراج</span>' + T.esc(info.director) + '</div>';
        if (info.cast || info.actors) cr += '<div><span>بطولة</span>' + T.esc(String(info.cast || info.actors).substr(0, 220)) + '</div>';
        U.$('td-cr-movie').innerHTML = cr;
      });
    },
    resume: function () { this.buttons(); favBtn('movie', this.item); },
    /* the film is a part of a series: all its parts, this one marked, a tap away */
    sagaRow: function () {
      var self = this, it = this.item, my = this.req;
      Sagas.ofItem(it, function (s, at) {
        var box = U.$('td-saga');
        if (!s || !box || my !== self.req || self.item !== it) return;
        self.saga = s;
        var h = '<section class="th-sec td-sagasec"><div class="th-sec-head"><h2>' + T.esc(s.name) + ' <span class="muted">' + T.esc(Sagas.partName(s, at)) + '</span></h2>' +
          '<button type="button" class="t-link" data-act="saga">كل السلسلة</button></div><div class="th-row r-poster" id="td-saga-row">';
        for (var i = 0; i < s.parts.length; i++) {
          var p = s.parts[i];
          h += '<button type="button" class="th-card' + (i === at ? ' cur' : '') + '" data-act="sp" data-i="' + i + '">' + T.pic(p.icon, p.name, 'poster') +
            '<b>' + T.esc(p.name) + '</b><small>' + T.esc(Sagas.partName(s, i) + (p.year ? ' · ' + p.year : '')) + '</small></button>';
        }
        box.innerHTML = h + '</div></section>';
        /* this part in view (the row runs right to left) */
        var row = U.$('td-saga-row'), cur = row && row.querySelector('.cur');
        if (cur && at > 1) {
          var rtl = window.getComputedStyle(row).direction === 'rtl';
          row.scrollLeft = (rtl ? -1 : 1) * Math.max(0, (at - 1) * (cur.offsetWidth + 12));
        }
      });
    },
    buttons: function () {
      var h = Store.getHist('m:' + this.item.id), html;
      if (h && !h.done && h.pos > 30000) {
        html = '<button type="button" class="t-btn" data-act="resume">' + T.ICON.play + 'استكمال من ' + U.fmtTime(h.pos) + '</button>' +
          '<button type="button" class="t-btn ghost" data-act="start">' + T.ICON.restart + 'من البداية</button>';
      } else {
        html = '<button type="button" class="t-btn" data-act="start">' + T.ICON.play + 'تشغيل</button>';
      }
      U.$('td-btns-movie').innerHTML = html;
    },
    onKey: function (k) { if (k === 'back') App.back(); }
  };

  /* ---------------- series ---------------- */
  Screens.t_series = {
    show: function (params) {
      var self = this, it = this.item = params.item;
      this.data = null;
      this.season = 0;
      frame(this.el, it, 'series');
      favBtn('series', it);
      U.$('td-btns-series').innerHTML = '';
      T.bind(this.el, {
        fav: function () { T.favToast(Store.toggleFav(self.item)); favBtn('series', self.item); },
        season: function (t) { self.season = parseInt(t.getAttribute('data-s'), 10); self.drawSeasons(); self.drawEpisodes(); },
        ep: function (t) { self.play(self.season, parseInt(t.getAttribute('data-e'), 10), false); },
        cont: function () { var p = self.continueAt(); if (p) self.play(p.s, p.e, false); },
        first: function () { self.play(0, 0, true); }
      });
      var my = this.req = (this.req || 0) + 1;
      Xtream.getSeriesInfo(it.id, function (err, data) {
        if (my !== self.req) return;
        if (err) { U.$('td-plot-series').innerHTML = '<span class="muted">' + T.esc(Xtream.errorText(err)) + '</span>'; return; }
        self.data = data;
        var info = data.info || {};
        U.setBg(U.$('td-bg-series'), backdropOf(info, it));
        var year = String(info.releaseDate || info.release_date || '').substr(0, 4);
        var r = parseFloat(info.rating) || it.rating;
        U.$('td-meta-series').innerHTML = chips([year && year !== '0000' ? year : '', data.seasons.length ? data.seasons.length + (data.seasons.length > 1 ? ' مواسم' : ' موسم') : '',
          r ? '★ ' + (Math.round(r * 10) / 10) : '', info.genre || '']);
        U.$('td-plot-series').innerHTML = T.esc(info.plot || 'لا يوجد وصف لهذا المسلسل.');
        U.$('td-cr-series').innerHTML = info.cast ? '<div><span>بطولة</span>' + T.esc(String(info.cast).substr(0, 220)) + '</div>' : '';
        if (!data.seasons.length) { U.$('td-eps').innerHTML = '<p class="t-empty-s">لا توجد حلقات متاحة.</p>'; return; }
        var at = self.continueAt();
        if (at) self.season = at.s;
        self.buttons();
        self.drawSeasons();
        self.drawEpisodes();
        if (params.autoplay && at) self.play(at.s, at.e, false);
      });
    },
    resume: function (result) {
      favBtn('series', this.item);
      if (!this.data) return;
      if (result && result.seasonIdx !== undefined) this.season = result.seasonIdx;
      this.buttons();
      this.drawSeasons();
      this.drawEpisodes();
    },

    find: function (epId) {
      var ss = this.data ? this.data.seasons : [];
      for (var s = 0; s < ss.length; s++) for (var e = 0; e < ss[s].episodes.length; e++) if (String(ss[s].episodes[e].id) === String(epId)) return { s: s, e: e };
      return null;
    },
    /* where "continue" goes: the last episode, or the one after it when it was finished */
    continueAt: function () {
      var last = Store.getHist('s:' + this.item.id);
      if (!last || !this.data) return null;
      var at = this.find(last.episodeId), ss = this.data.seasons;
      if (!at) return null;
      var eh = Store.getHist('e:' + last.episodeId);
      if (eh && eh.done) {
        if (at.e + 1 < ss[at.s].episodes.length) at = { s: at.s, e: at.e + 1 };
        else if (at.s + 1 < ss.length && ss[at.s + 1].episodes.length) at = { s: at.s + 1, e: 0 };
      }
      return at;
    },
    buttons: function () {
      var at = this.continueAt(), h = '';
      if (at) {
        var ep = this.data.seasons[at.s].episodes[at.e];
        h += '<button type="button" class="t-btn" data-act="cont">' + T.ICON.play + 'استكمال · م' + this.data.seasons[at.s].num + ' ح' + ep.num + '</button>' +
          '<button type="button" class="t-btn ghost" data-act="first">' + T.ICON.restart + 'من الحلقة الأولى</button>';
      } else {
        h += '<button type="button" class="t-btn" data-act="first">' + T.ICON.play + 'شاهد الحلقة الأولى</button>';
      }
      U.$('td-btns-series').innerHTML = h;
    },
    drawSeasons: function () {
      var ss = this.data.seasons, h = '<div class="t-chips">';
      for (var i = 0; i < ss.length; i++) {
        h += '<button type="button" class="t-chip' + (i === this.season ? ' on' : '') + '" data-act="season" data-s="' + i + '">الموسم ' + T.esc(String(ss[i].num)) + '</button>';
      }
      U.$('td-seasons').innerHTML = h + '</div>';
    },
    drawEpisodes: function () {
      var eps = this.data.seasons[this.season].episodes, h = '';
      for (var i = 0; i < eps.length; i++) {
        var ep = eps[i], hist = Store.getHist('e:' + ep.id), prog = '';
        if (hist && hist.done) prog = '<span class="td-done">تمت المشاهدة</span>';
        else if (hist && hist.pos > 30000 && hist.dur) prog = '<div class="t-bar"><i style="width:' + Math.min(100, Math.round(hist.pos / hist.dur * 100)) + '%"></i></div>';
        var title = ep.title && !/^episode\s*\d+$/i.test(ep.title) ? ep.title : '';
        h += '<button type="button" class="td-ep" data-act="ep" data-e="' + i + '">' +
          '<span class="td-ep-n">' + ep.num + '</span>' +
          (ep.image ? T.pic(ep.image, '', 'still') : '') +
          '<span class="td-ep-t"><b>الحلقة ' + ep.num + '</b>' + (title ? '<small>' + T.esc(title) + '</small>' : '') +
          (ep.duration ? '<small>' + T.esc(String(ep.duration).replace(/^00:/, '')) + '</small>' : '') + prog + '</span>' +
          '<span class="td-ep-play">' + T.ICON.play + '</span></button>';
      }
      U.$('td-eps').innerHTML = h;
    },
    play: function (s, e, fromStart) {
      var ep = this.data.seasons[s].episodes[e];
      var h = Store.getHist('e:' + ep.id);
      var startAt = (!fromStart && h && !h.done && h.pos > 30000) ? h.pos : 0;
      App.go('player', { kind: 'episode', series: this.item, seasons: this.data.seasons, seasonIdx: s, epIdx: e, startAt: startAt });
    },
    onKey: function (k) { if (k === 'back') App.back(); }
  };
})();

/* ==========================================================================
   A film series on a phone / tablet («سلاسل الأفلام»): its parts in the order
   they came out, what was watched of each, and one button that goes on from
   where the user stopped (or starts at the first part).
   ========================================================================== */
Screens.t_saga = {
  show: function (params) {
    var self = this, s = this.saga = params.saga;
    if (!s) { App.back(); return; }
    var el = this.el, mosaic = '';
    for (var m = 0; m < 4; m++) {
      var pic = s.parts[(s.parts.length - 1 - m + s.parts.length) % s.parts.length].icon;
      mosaic += '<i' + (pic ? ' style="background-image:url(\'' + U.esc(String(pic).replace(/'/g, '%27')) + '\')"' : '') + '></i>';
    }
    el.className = 'screen t-screen td tsg';
    el.innerHTML =
      '<div class="t-scroll td-scroll">' +
      '<div class="td-hero"><div class="tsg-mosaic">' + mosaic + '</div><div class="td-bg" id="tsg-bg"></div><div class="td-shade"></div></div>' +
      '<div class="td-top"><button type="button" class="t-ibtn glass t-back" data-act="back" aria-label="رجوع">' + T.ICON.back + '</button></div>' +
      '<div class="td-main"><div class="td-poster tsg-stack">' + this.stack(s) + '</div>' +
      '<div class="td-info"><span class="th-kicker">سلسلة أفلام</span><h1>' + T.esc(s.name) + '</h1>' +
      '<div class="tsg-en">' + T.esc(s.alt || '') + '</div>' +
      '<div class="td-meta">' + this.chips(s) + '</div>' +
      '<div class="td-btns" id="tsg-btns"></div></div></div>' +
      '<div class="tsg-parts" id="tsg-parts"></div></div>';
    T.bind(el, {
      go: function () { self.goOn(); },
      part: function (t) { var it = self.saga.parts[parseInt(t.getAttribute('data-i'), 10)]; if (it) App.go('movie', { item: it }); },
      play: function (t, e) { if (e && e.stopPropagation) e.stopPropagation(); self.play(parseInt(t.getAttribute('data-i'), 10)); }
    });
    this.draw();
    this.backdrop();
  },
  resume: function () { if (this.saga) this.draw(); },
  onKey: function (k) { if (k === 'back') App.back(); },

  stack: function (s) { return T.sagaPile(s); },
  chips: function (s) {
    var r = 0, n = 0, h = '<span class="td-chip">' + Sagas.partsText(s.count) + '</span>';
    for (var i = 0; i < s.parts.length; i++) if (s.parts[i].rating) { r += s.parts[i].rating; n++; }
    if (s.from) h += '<span class="td-chip">' + T.esc(Sagas.yearsText(s)) + '</span>';
    if (n) h += '<span class="td-chip">★ ' + (Math.round(r / n * 10) / 10) + '</span>';
    return h;
  },

  /* where "go on" starts: a part half watched, or the one after the last finished, or the first */
  next: function () {
    var parts = this.saga.parts, lastDone = -1;
    for (var i = 0; i < parts.length; i++) {
      var h = Store.getHist('m:' + parts[i].id);
      if (h && !h.done && h.pos > 30000) return { i: i, resume: h.pos };
      if (h && h.done) lastDone = i;
    }
    if (lastDone >= 0 && lastDone + 1 < parts.length) return { i: lastDone + 1, resume: 0, after: true };
    return { i: 0, resume: 0, again: lastDone === parts.length - 1 };
  },
  draw: function () {
    var s = this.saga, nx = this.next(), label;
    if (nx.resume) label = 'استكمال ' + Sagas.partName(s, nx.i);
    else if (nx.after) label = 'شاهد ' + Sagas.partName(s, nx.i);
    else label = nx.again ? 'شاهد السلسلة من جديد' : (s.nums && s.nums[0] > 1 ? 'شاهد ' + Sagas.partName(s, 0) : 'شاهد من الجزء الأول');
    U.$('tsg-btns').innerHTML = '<button type="button" class="t-btn" data-act="go">' + T.ICON.play + label + '</button>';
    var h = '';
    for (var i = 0; i < s.parts.length; i++) {
      var it = s.parts[i], hist = Store.getHist('m:' + it.id), meta = [], prog = '';
      if (it.year) meta.push(String(it.year));
      if (it.rating) meta.push('★ ' + it.rating);
      if (hist && hist.done) prog = '<span class="td-done">تمت المشاهدة</span>';
      else if (hist && hist.pos > 30000 && hist.dur) prog = '<div class="t-bar"><i style="width:' + Math.min(100, Math.round(hist.pos / hist.dur * 100)) + '%"></i></div>';
      h += '<button type="button" class="tsg-part' + (i === nx.i && (nx.resume || nx.after) ? ' next' : '') + '" data-act="part" data-i="' + i + '">' +
        '<span class="tsg-pic">' + T.pic(it.icon, it.name, 'poster') + '<span class="tsg-num">' + (i + 1) + '</span></span>' +
        '<span class="tsg-t"><small class="tsg-k">' + Sagas.partName(s, i) + '</small><b>' + T.esc(it.name) + '</b>' +
        (meta.length ? '<small>' + T.esc(meta.join(' · ')) + '</small>' : '') + prog + '</span>' +
        '<span class="td-ep-play" data-act="play" data-i="' + i + '" aria-label="تشغيل">' + T.ICON.play + '</span></button>';
    }
    U.$('tsg-parts').innerHTML = h;
  },
  goOn: function () {
    var nx = this.next();
    this.play(nx.i, nx.resume);
  },
  play: function (i, at) {
    var it = this.saga.parts[i];
    if (!it) return;
    if (at === undefined) { var h = Store.getHist('m:' + it.id); at = h && !h.done && h.pos > 30000 ? h.pos : 0; }
    App.go('player', { kind: 'movie', item: it, startAt: at || 0 });
  },

  /* the wide picture of the newest part, once it has arrived (the posters stand in until then) */
  backdrop: function () {
    var s = this.saga, it = s.parts[s.parts.length - 1], my = this.req = (this.req || 0) + 1, self = this;
    Xtream.getVodInfo(it.id, function (err, data) {
      if (err || my !== self.req || App.current() !== 't_saga') return;
      var info = (data && data.info) || {}, b = info.backdrop_path;
      if (b && typeof b !== 'string') b = b[0];
      if (!b) return;
      var img = new Image();
      img.onload = function () {
        var bg = U.$('tsg-bg');
        if (!bg || my !== self.req) return;
        U.setBg(bg, b);
        U.addClass(bg, 'on');
      };
      img.src = U.bgUrl(b);
    });
  }
};

/* ==========================================================================
   Search on a phone / tablet. Opened from a tab it searches that tab only
   (films from Films, series from Series, channels from Live); opened from
   home it searches everything. Results start from the first letter: names
   that begin with what was typed come first, then names with a word that
   begins with it, then (from two letters) names that contain it.
   ========================================================================== */
(function () {
  var TYPES = [
    { id: 'all', name: 'الكل' }, { id: 'live', name: 'القنوات' }, { id: 'vod', name: 'الأفلام' }, { id: 'series', name: 'المسلسلات' }
  ];
  var HINT = {
    all: 'اكتب أول حروف اسم القناة أو الفيلم أو المسلسل.',
    live: 'اكتب أول حروف اسم القناة.',
    vod: 'اكتب أول حروف اسم الفيلم.',
    series: 'اكتب أول حروف اسم المسلسل.'
  };
  var PLACE = { all: 'قناة أو فيلم أو مسلسل', live: 'اسم القناة', vod: 'اسم الفيلم', series: 'اسم المسلسل' };
  var MAX = 300, CHUNK = 48;

  var S = Screens.t_search = { q: '', type: 'all', req: 0, res: {}, lists: {} };

  S.show = function (params) {
    var self = this, el = this.el;
    params = params || {};
    this.type = params.type && params.type !== 'fav' ? params.type : 'all';
    this.q = '';
    this.res = {};
    el.className = 'screen t-screen ts';
    el.innerHTML = T.top({ back: true, title: 'بحث' }) +
      '<div class="ts-box"><div class="t-field big">' + T.ICON.search +
      '<input id="ts-in" type="search" inputmode="search" enterkeyhint="search" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false"></div><div class="t-seg ts-seg" id="ts-seg"></div></div>' +
      '<div class="t-scroll ts-res" id="ts-res"></div>';
    var inp = U.$('ts-in');
    var run = U.debounce(function () { if (inp.value !== self.q) self.run(inp.value); }, 160);
    inp.addEventListener('input', run);
    inp.addEventListener('keydown', function (e) { if (e.keyCode === 13) { inp.blur(); self.run(inp.value); } });
    /* scrolling the results hides the keyboard so they can be seen */
    var res = U.$('ts-res');
    res.addEventListener('touchmove', function () { if (document.activeElement === inp) inp.blur(); }, { passive: true });
    res.addEventListener('scroll', function () { self.more(); }, { passive: true });
    T.bind(el, {
      type: function (t) { self.setType(t.getAttribute('data-id')); },
      item: function (t) { self.open(t.getAttribute('data-k'), parseInt(t.getAttribute('data-i'), 10)); },
      more: function (t) { self.setType(t.getAttribute('data-k')); }
    });
    this.setType(this.type, true);
    setTimeout(function () { try { inp.focus(); } catch (e) {} }, 250);
  };

  S.resume = function () { this.draw(); };

  S.setType = function (type, first) {
    this.type = type;
    var h = '';
    for (var i = 0; i < TYPES.length; i++) {
      h += '<button type="button" class="' + (TYPES[i].id === type ? 'on' : '') + '" data-act="type" data-id="' + TYPES[i].id + '">' + TYPES[i].name + '</button>';
    }
    U.$('ts-seg').innerHTML = h;
    var inp = U.$('ts-in');
    inp.placeholder = PLACE[type];
    if (!first) U.$('ts-res').scrollTop = 0;
    this.run(inp.value);
  };

  /* the whole list of a type, with simplified names kept for quick matching */
  S.load = function (type, cb) {
    var self = this, acct = Store.acctKey();
    if (this.lists.acct !== acct) this.lists = { acct: acct };
    if (this.lists[type]) return cb(this.lists[type]);
    Xtream.getStreams(type, null, function (err, all) {
      if (err || !all) return cb(null, err);
      all = Parental.filter(type, all);
      var names = [];
      for (var i = 0; i < all.length; i++) names.push(' ' + Xtream.simplify(all[i].name).replace(/[^0-9a-z؀-ۿ]+/g, ' '));
      self.lists[type] = { items: all, names: names };
      cb(self.lists[type]);
    });
  };

  S.match = function (L, q) {
    q = Xtream.simplify(q).replace(/[^0-9a-z؀-ۿ]+/g, ' ').replace(/^\s+|\s+$/g, '');
    if (!q) return [];
    var start = [], word = [], inside = [], items = L.items, names = L.names, wq = ' ' + q;
    for (var i = 0; i < items.length; i++) {
      var n = names[i], p = n.indexOf(wq);
      if (p === 0) start.push(items[i]);
      else if (p > 0) word.push(items[i]);
      else if (q.length > 1 && n.indexOf(q) !== -1) inside.push(items[i]);
      if (start.length >= MAX) break;
    }
    return start.concat(word, inside).slice(0, MAX);
  };

  S.run = function (q) {
    var self = this;
    q = String(q || '').replace(/^\s+|\s+$/g, '');
    this.q = q;
    var my = ++this.req;
    this.sagaHits = [];
    if (!q) { this.res = {}; this.draw(); return; }
    var types = this.type === 'all' ? ['live', 'vod', 'series'] : [this.type];
    this.res = {};
    /* a film series whose name was typed comes first ("هاري" → the Harry Potter films) */
    if (this.type === 'all' || this.type === 'vod') {
      Sagas.find(q, function (hits) {
        if (my !== self.req || !hits.length) return;
        self.sagaHits = hits;
        self.draw();
      });
    }
    types.forEach(function (t) { self.res[t] = null; });
    this.draw();
    types.forEach(function (t) {
      self.load(t, function (L) {
        if (my !== self.req) return;
        self.res[t] = L ? self.match(L, q) : [];
        self.draw();
      });
    });
  };

  S.card = function (k, it, i) {
    if (k === 'live') {
      return '<button type="button" class="ts-ch" data-act="item" data-k="live" data-i="' + i + '">' + T.pic(it.icon, it.name, 'logo') +
        '<b>' + T.esc(it.name) + '</b></button>';
    }
    var sub = it.year ? String(it.year) + (it.rating ? ' · ★ ' + it.rating : '') : (it.rating ? '★ ' + it.rating : '');
    return '<button type="button" class="th-card" data-act="item" data-k="' + k + '" data-i="' + i + '">' + T.pic(it.icon, it.name, 'poster') +
      '<b>' + T.esc(it.name) + '</b>' + (sub ? '<small>' + T.esc(sub) + '</small>' : '') + '</button>';
  };

  S.sagaRow = function () {
    var hs = this.sagaHits || [], h = '';
    if (!hs.length || (this.type !== 'all' && this.type !== 'vod')) return '';
    for (var i = 0; i < hs.length; i++) {
      h += '<button type="button" class="th-card" data-act="item" data-k="saga" data-i="' + i + '">' + T.sagaPile(hs[i]) +
        '<b>' + T.esc(hs[i].name) + '</b><small>' + T.esc(Sagas.partsText(hs[i].count)) + '</small></button>';
    }
    return '<section class="th-sec ts-sagas"><div class="th-sec-head"><h2>سلاسل الأفلام</h2></div><div class="th-row r-saga">' + h + '</div></section>';
  };

  S.draw = function () {
    var box = U.$('ts-res');
    if (!box) return;
    if (!this.q) { box.innerHTML = '<p class="t-empty-s">' + HINT[this.type] + '</p>'; return; }
    var NAMES = { live: 'القنوات', vod: 'الأفلام', series: 'المسلسلات' }, h = '', any = false, waiting = false, i;
    if (this.type !== 'all') {
      var k = this.type, list = this.res[k];
      if (list === null || list === undefined) { box.innerHTML = '<div class="t-state inline"><div class="t-spin"></div></div>'; return; }
      if (!list.length && !this.sagaRow()) { box.innerHTML = '<p class="t-empty-s">لا توجد نتائج لـ «' + T.esc(this.q) + '».</p>'; return; }
