      h += '<div class="' + (kk === 'live' ? 'ts-list' : 'th-row r-poster') + '">';
      /* everything at once: a few channels, then the films and series as posters */
      for (i = 0; i < ls.length && i < (kk === 'live' ? 5 : 12); i++) h += this.card(kk, ls[i], i);
      h += '</div></section>';
    }
    if (waiting) h += '<div class="t-state inline"><div class="t-spin"></div></div>';
