  }

  /* swipe on the picture */
  function swipeVideo(dx, dy) {
    var s = scr('player');
    if (s.zapOpen || s.epsOpen) return false;
    var ax = Math.abs(dx), ay = Math.abs(dy);
    if (Math.max(ax, ay) < 60) return false;
    if (s.isLive()) {
      if (ay > ax) { s.zapTo(s.p.index + (dy < 0 ? 1 : -1)); return true; }
      return false;
    }
    if (ax > ay) {
      /* the timeline runs left-to-right: swipe right = forward */
      s.seekBy(dx > 0 ? 10 : -10);
      return true;
    }
    return false;
  }

  /* ---------------- floating pad ---------------- */
  var PAD_ICON = '<svg viewBox="0 0 24 24"><path d="M15 7.5V2H9v5.5l3 3 3-3zM7.5 9H2v6h5.5l3-3-3-3zM9 16.5V22h6v-5.5l-3-3-3 3zM16.5 9l-3 3 3 3H22V9h-5.5z"/></svg>';

  function buildPad() {
    var b = document.createElement('div');
    b.id = 'tpad-btn';
    b.innerHTML = PAD_ICON;
    var pad = document.createElement('div');
    pad.id = 'tpad';
    pad.innerHTML =
      '<div class="row"><div class="k" data-k="up">▲</div></div>' +
      '<div class="row"><div class="k" data-k="left">◀</div><div class="k ok" data-k="enter">OK</div><div class="k" data-k="right">▶</div></div>' +
      '<div class="row"><div class="k" data-k="down">▼</div></div>' +
      '<div class="row"><div class="k wide" data-k="back">رجوع</div><div class="k wide" data-k="close">إخفاء</div></div>';
    document.body.appendChild(b);
    document.body.appendChild(pad);

    function toggle(on) { U.toggleClass(pad, 'open', on); }
    b.addEventListener('click', function (e) { e.stopPropagation(); toggle(pad.className.indexOf('open') === -1); });

    var rep = null, repTimer = null;
    function release() { clearTimeout(repTimer); clearInterval(rep); rep = null; var on = pad.querySelectorAll('.on'); for (var i = 0; i < on.length; i++) U.removeClass(on[i], 'on'); }
    function press(k, el) {
      U.addClass(el, 'on');
      if (k === 'close') { toggle(false); return; }
      key(k);
      if (k === 'up' || k === 'down' || k === 'left' || k === 'right') {
        /* hold an arrow to keep moving */
        repTimer = setTimeout(function () { rep = setInterval(function () { key(k); }, 120); }, 450);
      }
    }
    pad.addEventListener('touchstart', function (e) {
      var el = closest(e.target, '.k');
      e.preventDefault();
      if (el) press(el.getAttribute('data-k'), el);
    }, { passive: false });
    pad.addEventListener('touchend', function (e) { e.preventDefault(); release(); }, { passive: false });
    pad.addEventListener('touchcancel', release);
    /* mouse (testing on a computer) */
    pad.addEventListener('mousedown', function (e) { var el = closest(e.target, '.k'); if (el) press(el.getAttribute('data-k'), el); });
    pad.addEventListener('mouseup', release);
    pad.addEventListener('click', function (e) { e.stopPropagation(); });
  }

  /* while a film plays with its controls hidden, the car's floating Back / Home buttons step aside */
  var videoOn = false;
  function watchVideo() {
    var on = false;
    try {
      on = screenName() === 'player' && !UI.modal() && !scr('player').osdVisible() &&
        !scr('player').zapOpen && !scr('player').epsOpen && Player.state() !== 'idle';
    } catch (e) { on = false; }
    if (on !== videoOn) {
      videoOn = on;
      try { if (window.AndroidApp && AndroidApp.videoMode) AndroidApp.videoMode(on); } catch (e) {}
    }
  }

  function init() {
    setInterval(watchVideo, 500);
    document.addEventListener('touchstart', onStart, { passive: true });
    document.addEventListener('click', function (e) {
      if (U.now() - lastGesture < 400) { e.preventDefault(); e.stopPropagation(); return; }
      onTap(e);
    }, true);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
